            input_types=["Data", "JSON", "Message"],
            required=False,
            advanced=False,
            info="42 질문 카드의 Submit Answers branch가 자동 연결됩니다.",
        ),
        DataInput(
            name="skip_trigger",
            display_name="추가 입력 건너뛰기 Trigger",
            input_types=["Data", "JSON", "Message"],
            required=False,
