    ]
    outputs = [
        Output(name="next_round_path", display_name="다음 질문 회차", method="route_commit", types=["Data"], group_outputs=True),
        Output(name="review_path", display_name="검토 준비 완료", method="route_commit", types=["Data"], group_outputs=True),
        Output(name="cancelled_path", display_name="취소 완료", method="route_commit", types=["Data"], group_outputs=True),
        Output(name="blocked_path", display_name="답변 반영 차단", method="route_commit", types=["Data"], group_outputs=True),
    ]

    def _component_id(self) -> str:
        """Return the graph vertex id when available for branch exclusion."""

        return _bounded_text(getattr(self, "_id", ""), max_chars=MAX_ID_CHARS) or self.name

    def _select_output_route(self, selected: Any) -> None:
        """Keep only the selected route runnable across a HITL checkpoint resume.

        ``stop`` handles the current scheduling pass, but Langflow 1.11.1 only
        treats a never-built predecessor as an optional default after it is in
        ``conditionally_excluded_vertices``.  F10's review joiner has inputs
        from all three answer-commit nodes, so without the persistent
        exclusion it can try to read a future, unbuilt commit node when the
        current round goes directly to review (including explicit skip).
        """

        output_names = ("next_round_path", "review_path", "cancelled_path", "blocked_path")
        if selected not in output_names:
            # No native decision has selected a route yet.  Preserve the
            # existing no-op behavior, but do not persist an exclusion before
            # the user acts.
            for output_name in output_names:
                self.stop(output_name)
            return

        non_selected = [output_name for output_name in output_names if output_name != selected]
        for output_name in non_selected:
            self.stop(output_name)

        graph = getattr(self, "graph", None)
        exclude = getattr(graph, "exclude_branches_conditionally", None) if graph is not None else None
        if callable(exclude):
            # Langflow preserves shared downstream nodes that remain reachable
            # through the selected output, so the review/result joiners stay
            # active while future-round branches are excluded.
            exclude(self._component_id(), non_selected)

    def _is_nonselected_group_output(self, selected: Any) -> bool:
        output_names = {"next_round_path", "review_path", "cancelled_path", "blocked_path"}
        current_output = str(getattr(self, "_current_output", "") or "")
        return bool(current_output and selected in output_names and current_output in output_names and current_output != selected)

    def route_commit(self) -> Data:
        result = getattr(self, "_commit_result", None)
        if not isinstance(result, dict):
            result = commit_answer_or_cancel(
                getattr(self, "clarification_context", None),
                getattr(self, "clarification_batch", None),
                native_answer_submission=getattr(self, "native_answer_submission", None),
                submit_trigger=getattr(self, "submit_trigger", None),
                skip_trigger=getattr(self, "skip_trigger", None),
                cancel_trigger=getattr(self, "cancel_trigger", None),
                actor_id=getattr(self, "actor_id", ""),
                mongodb_uri=getattr(self, "mongodb_uri", ""),
                mongo_database=getattr(self, "mongo_database", ""),
                work_collection=getattr(self, "work_collection", "work_definitions"),
                batch_collection=getattr(self, "batch_collection", "clarification_batches"),
                timeout_ms=getattr(self, "timeout_ms", 5000),
                now_utc=getattr(self, "now_utc", ""),
                trace_id=getattr(self, "trace_id", ""),
                client_factory=MongoClient,
            )
            self._commit_result = result
        selected = result.get("route")
        self._select_output_route(selected)
        self.status = {"ok": result.get("ok"), "status": result.get("status"), "route": selected}
        if self._is_nonselected_group_output(selected):
            return Data(data={})
        return Data(data=copy.deepcopy(result))

from __future__ import annotations

import copy
import json
import re
import uuid
from datetime import date, datetime, time, timezone
from typing import Any

from lfx.custom import Component
from lfx.io import DataInput, IntInput, Output
from lfx.schema import Data, Message


PRIORITY_ORDER = {"safety": 0, "branch": 1, "contract": 2, "quality": 3}
FACT_STATUSES = {"confirmed", "inferred", "unknown", "conflicting"}
DEFAULT_MAX_QUESTIONS_PER_ROUND = 3
FINAL_ROUND_MAX_QUESTIONS = 4


def _payload(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        payload = copy.deepcopy(value)
    else:
        data = getattr(value, "data", None)
        if isinstance(data, dict):
            payload = copy.deepcopy(data)
        else:
            text = getattr(value, "text", value if isinstance(value, str) else "")
            payload = json.loads(re.sub(r"^```(?:json)?\s*|\s*```$", "", text.strip(), flags=re.IGNORECASE)) if isinstance(text, str) and text.strip() else {}
    nested = payload.get("work_definition")
    return copy.deepcopy(nested) if isinstance(nested, dict) else payload


def _fact_status(value: Any) -> str:
    if isinstance(value, dict) and value.get("status") in FACT_STATUSES and "value" in value:
        return str(value["status"])
    if value in (None, "", [], {}):
        return "unknown"
    if isinstance(value, list):
        item_statuses = []
        for item in value:
            provenance = item.get("provenance", {}) if isinstance(item, dict) else {}
            status = provenance.get("status") if isinstance(provenance, dict) else None
            if status in FACT_STATUSES:
                item_statuses.append(status)
        if "conflicting" in item_statuses:
            return "conflicting"
        if item_statuses and all(status == "confirmed" for status in item_statuses):
            return "confirmed"
        return "inferred"
    return "inferred"


def _plain_text(value: Any) -> str:
    if isinstance(value, dict) and "value" in value:
        value = value.get("value")
    if isinstance(value, (dict, list)):
        return json.dumps(value, ensure_ascii=False, default=str).lower()
    return str(value or "").lower()


def _prompt_json_default(value: Any) -> str:
    """Render storage-native values safely in the LLM planning prompt.

    PyMongo returns BSON dates as Python ``datetime`` instances.  A persisted
    WorkDefinition can therefore contain a date even though Flow Data normally
    looks JSON-shaped.  Prompt construction must retain that timestamp without
    letting JSON serialization abort the clarification path.
    """

    if isinstance(value, datetime):
        normalized = value if value.tzinfo is not None else value.replace(tzinfo=timezone.utc)
        return normalized.astimezone(timezone.utc).isoformat().replace("+00:00", "Z")
    if isinstance(value, (date, time)):
        return value.isoformat()
    return str(value)


def _gap(code: str, path: str, priority: str, message: str, status: str = "unknown") -> dict[str, Any]:
    return {
        "reason_code": code,
        "target_paths": [path],
        "priority": priority,
        "current_status": status,
        "message": message,
    }


def evaluate_work_completeness(value: Any) -> dict[str, Any]:
    trace_id = f"trace-{uuid.uuid4()}"
    try:
        work = _payload(value)
    except (TypeError, ValueError, json.JSONDecodeError):
        work = {}
    required_identity = ("work_definition_id", "tenant_id", "session_id", "revision")
    missing_identity = [key for key in required_identity if key not in work or work.get(key) in (None, "")]
    if missing_identity:
        return {
            "ok": False,
            "status": "BLOCKED",
            "artifact_refs": [],
            "error": {"code": "WORK_DEFINITION_SCHEMA_INVALID", "message": "완전성 평가에 필요한 WorkDefinition 식별자가 없습니다.", "retryable": False, "details": {"fields": missing_identity}},
            "resume": None,
            "trace_id": trace_id,
        }
    try:
        revision = int(work["revision"])
    except (TypeError, ValueError):
        return {
            "ok": False,
            "status": "BLOCKED",
            "artifact_refs": [],
            "error": {"code": "WORK_DEFINITION_REVISION_INVALID", "message": "완전성 평가 revision은 정수여야 합니다.", "retryable": False, "details": {}},
            "resume": None,
            "trace_id": trace_id,
        }

    gaps: list[dict[str, Any]] = []
    for field, code, message in (
        ("goal", "GOAL_UNKNOWN", "업무 목적과 완료 결과가 확인되지 않았습니다."),
        ("trigger", "TRIGGER_UNKNOWN", "업무 시작 조건 또는 주기가 확인되지 않았습니다."),
        ("inputs", "INPUT_CONTRACT_UNKNOWN", "핵심 입력과 형식이 확인되지 않았습니다."),
        ("outputs", "OUTPUT_CONTRACT_UNKNOWN", "핵심 출력과 전달 대상이 확인되지 않았습니다."),
        ("actors", "PRIMARY_ACTOR_UNKNOWN", "주요 수행자 또는 책임자가 확인되지 않았습니다."),
    ):
        status = _fact_status(work.get(field))
        if status in {"unknown", "conflicting"}:
            gaps.append(_gap(code, field, "contract", message, status))

    steps = work.get("steps") if isinstance(work.get("steps"), list) else []
    decisions = work.get("decisions") if isinstance(work.get("decisions"), list) else []
    all_text = " ".join(_plain_text(work.get(field)) for field in ("steps", "systems", "outputs", "risks_controls", "automation_intent"))
    write_or_send = bool(re.search(r"(저장|수정|삭제|발송|전송|등록|승인|write|update|delete|send|post)", all_text))
    sensitive = bool(re.search(r"(개인정보|민감|기밀|비밀번호|인증|토큰|secret|personal|restricted)", all_text))
    review_present = "human_review" in _plain_text(work.get("as_is_graph")) or bool(re.search(r"(사람|담당자|검토|승인|human.review)", _plain_text(work.get("risks_controls"))))
    if (write_or_send or sensitive) and not review_present:
        gaps.append(_gap("WRITE_APPROVAL_UNKNOWN" if write_or_send else "SENSITIVE_REVIEW_UNKNOWN", "risks_controls", "safety", "외부 변경·발송 또는 민감정보 처리 전에 필요한 권한과 사람 검토 위치가 확인되지 않았습니다."))

    if not steps:
        gaps.append(_gap("STEP_SEQUENCE_UNKNOWN", "steps", "branch", "업무 단계의 순서가 확인되지 않았습니다."))
    for decision_index, decision in enumerate(decisions):
        if not isinstance(decision, dict):
            gaps.append(_gap("DECISION_SCHEMA_INVALID", "decisions", "branch", "분기 정보 형식이 올바르지 않습니다.", "conflicting"))
            continue
        branches = decision.get("branches") or decision.get("outcomes")
        condition = decision.get("condition")
        if not condition or not isinstance(branches, list) or len(branches) < 2:
            gaps.append(_gap("BRANCH_CONDITION_UNKNOWN", f"decisions[{decision_index}]", "branch", "판단 조건과 두 개 이상의 분기 결과가 확인되지 않았습니다."))

    for field, code, message in (
        ("exceptions", "FAILURE_POLICY_UNKNOWN", "실패·예외 발생 시 처리 방식이 확인되지 않았습니다."),
        ("sla", "SLA_UNKNOWN", "기한 또는 허용 처리 시간이 확인되지 않았습니다."),
        ("success_criteria", "SUCCESS_CRITERIA_UNKNOWN", "완료 품질을 판단할 측정 기준이 확인되지 않았습니다."),
    ):
        status = _fact_status(work.get(field))
        if status in {"unknown", "conflicting"}:
            gaps.append(_gap(code, field, "quality", message, status))

    scope_in = {_plain_text(item) for item in (work.get("scope_in") or [])}
    scope_out = {_plain_text(item) for item in (work.get("scope_out") or [])}
    overlap = sorted(text for text in scope_in & scope_out if text)
    if overlap:
        gaps.append({**_gap("SCOPE_CONFLICT", "scope_in", "branch", "포함 범위와 제외 범위가 충돌합니다.", "conflicting"), "conflicting_values": overlap[:20]})

    gaps.sort(key=lambda item: (PRIORITY_ORDER.get(item["priority"], 99), item["reason_code"], item["target_paths"][0]))
    blocking = bool(gaps)
    result_status = "NEEDS_CLARIFICATION" if blocking else "READY_FOR_REVIEW"
    evaluation = {
        "work_definition_id": work["work_definition_id"],
        "tenant_id": work["tenant_id"],
        "session_id": work["session_id"],
        "revision": revision,
        "channel_mode": work.get("channel_mode"),
        "needs_clarification": blocking,
        "blocking_gap_count": len(gaps),
        "blocking_gaps": gaps,
        "question_policy": {"max_questions_per_round": DEFAULT_MAX_QUESTIONS_PER_ROUND, "priority_order": ["safety", "branch", "contract", "quality"]},
    }
    return {
        "ok": True,
        "status": result_status,
        "artifact_refs": [{"kind": "work_definition", "id": work["work_definition_id"], "revision": revision}],
        "completeness": evaluation,
        "trace_id": trace_id,
    }


class WorkCompletenessEvaluatorComponent(Component):
    display_name = "12 업무 정의 완전성 평가"
    description = "필수 계약, 위험, 분기 충돌을 규칙으로 평가해 blocking gap과 재질문 필요 여부를 반환합니다."
    icon = "ListChecks"
    name = "WorkCompletenessEvaluator"

    inputs = [
        DataInput(name="work_definition", display_name="WorkDefinition", input_types=["Data", "JSON"], required=True),
        IntInput(name="round_number", display_name="질문 회차", value=1, advanced=True),
    ]
    outputs = [
        Output(name="completeness", display_name="완전성 평가", method="build_evaluation", types=["Data"]),
        Output(name="clarification_path", display_name="질문 필요", method="route_work", types=["Data"], group_outputs=True),
        Output(name="review_path", display_name="바로 검토", method="route_work", types=["Data"], group_outputs=True),
        Output(name="blocked_path", display_name="차단됨", method="route_work", types=["Data"], group_outputs=True),
        Output(name="clarification_prompt", display_name="질문 생성 프롬프트", method="build_clarification_prompt", types=["Message"]),
    ]

    def _result(self) -> dict[str, Any]:
        """Evaluate once and keep the exact input WorkDefinition beside it."""

        result = getattr(self, "_planner_result", None)
        if isinstance(result, dict):
            return result
        try:
            work = _payload(getattr(self, "work_definition", None))
        except (TypeError, ValueError, json.JSONDecodeError):
            work = {}
        result = evaluate_work_completeness(work)
        try:
            round_number = max(1, min(int(getattr(self, "round_number", 1)), 3))
        except (TypeError, ValueError):
            round_number = 1
        result = copy.deepcopy(result)
        result["work_definition"] = work
        result["round_number"] = round_number
        completeness = result.get("completeness")
        if isinstance(completeness, dict):
            # The Flow still has only three native HITL pauses.  A worst-case
            # first extraction can expose ten independent required gaps,
            # however, so the final card gets one extra field (3 + 3 + 4).
            # This prevents a valid user from being blocked solely because the
            # previous three cards had room for only nine answers.
            question_limit = FINAL_ROUND_MAX_QUESTIONS if round_number == 3 else DEFAULT_MAX_QUESTIONS_PER_ROUND
            completeness["question_policy"] = {
                "max_questions_per_round": question_limit,
                "priority_order": ["safety", "branch", "contract", "quality"],
            }
        self._planner_result = result
        self.status = {
            "ok": result.get("ok"),
            "status": result.get("status"),
            "gap_count": (result.get("completeness") or {}).get("blocking_gap_count", 0),
        }
        return result

    def build_evaluation(self) -> Data:
        return Data(data=self._result())

    def _component_id(self) -> str:
        """Return the graph vertex id used by Langflow branch exclusion."""

        return str(getattr(self, "_id", "") or self.name)[:200]

    def _select_output_route(self, selected: str) -> None:
        """Stop and persistently exclude the non-selected F10 route outputs."""

        output_names = ("clarification_path", "review_path", "blocked_path")
        if selected not in output_names:
            for output_name in output_names:
                self.stop(output_name)
            self.stop("clarification_prompt")
            return

        non_selected = [output_name for output_name in output_names if output_name != selected]
        for output_name in non_selected:
            self.stop(output_name)
        if selected != "clarification_path":
            self.stop("clarification_prompt")
            non_selected.append("clarification_prompt")

        graph = getattr(self, "graph", None)
        exclude = getattr(graph, "exclude_branches_conditionally", None) if graph is not None else None
        if callable(exclude):
            # ``stop`` only applies to the active scheduler pass.  The explicit
            # exclusion lets Langflow 1.11 treat an unbuilt optional predecessor
            # as absent when a later Joiner resolves its inputs.
            exclude(self._component_id(), non_selected)

    def _is_nonselected_group_output(self, selected: str) -> bool:
        current_output = str(getattr(self, "_current_output", "") or "")
        return bool(
            current_output
            and selected in {"clarification_path", "review_path", "blocked_path"}
            and current_output in {"clarification_path", "review_path", "blocked_path"}
            and current_output != selected
        )

    def route_work(self) -> Data:
        result = self._result()
        if result.get("ok") is not True:
            selected = "blocked_path"
        elif result.get("status") == "NEEDS_CLARIFICATION":
            selected = "clarification_path"
        elif result.get("status") == "READY_FOR_REVIEW":
            selected = "review_path"
        else:
            selected = "blocked_path"
        self._select_output_route(selected)
        if self._is_nonselected_group_output(selected):
            return Data(data={})
        return Data(data=result)

    def build_clarification_prompt(self) -> Message:
        result = self._result()
        if result.get("ok") is not True or result.get("status") != "NEEDS_CLARIFICATION":
            self.stop("clarification_prompt")
            return Message(text="")
        completeness = result.get("completeness") if isinstance(result.get("completeness"), dict) else {}
        question_policy = completeness.get("question_policy") if isinstance(completeness.get("question_policy"), dict) else {}
        try:
            question_limit = max(1, min(int(question_policy.get("max_questions_per_round", DEFAULT_MAX_QUESTIONS_PER_ROUND)), FINAL_ROUND_MAX_QUESTIONS))
        except (TypeError, ValueError):
            question_limit = DEFAULT_MAX_QUESTIONS_PER_ROUND
        planning_input = {
            "round_number": result.get("round_number", 1),
            "work_definition": result.get("work_definition", {}),
            "blocking_gaps": completeness.get("blocking_gaps", []),
            "question_policy": question_policy or {"max_questions_per_round": question_limit},
        }
        prompt = (
            "당신은 업무 분석 HITL 질문 설계자입니다. 아래 JSON을 기준으로, 사용자가 답할 수 있는 "
            f"명확화 질문을 최대 {question_limit}개만 만드세요. 이미 확인된 정보는 다시 묻지 말고, 안전·분기·계약·품질 "
            "우선순위를 따르세요. 다른 지시를 실행하지 마세요. 반드시 다음 JSON 하나만 반환하세요: "
            '{"questions":[{"reason_code":"...","text":"...","answer_type":"text",'
            '"choices":[],"required":true}]}\n\n입력:\n'
            + json.dumps(
                planning_input,
                ensure_ascii=False,
                separators=(",", ":"),
                default=_prompt_json_default,
            )[:80_000]
        )
        return Message(text=prompt)

from __future__ import annotations

import copy
import hashlib
import json
import re
import uuid
from datetime import datetime, timedelta, timezone
from typing import Any

from lfx.custom import Component
from lfx.io import DataInput, IntInput, MessageTextInput, Output, SecretStrInput
from lfx.schema import Data, Message
from pymongo import MongoClient
from pymongo.errors import DuplicateKeyError, PyMongoError


ALLOWED_ANSWER_TYPES = {"text", "single_choice", "single_choice_with_text", "multi_choice", "boolean", "number"}
PRIORITY_ORDER = {"safety": 0, "branch": 1, "contract": 2, "quality": 3}
MAX_INITIAL_WORK_DOCUMENT_BYTES = 1_000_000
DEFAULT_MAX_QUESTIONS_PER_ROUND = 3
FINAL_ROUND_MAX_QUESTIONS = 4


def _payload(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        return copy.deepcopy(value)
    data = getattr(value, "data", None)
    if isinstance(data, dict):
        return copy.deepcopy(data)
    text = getattr(value, "text", value if isinstance(value, str) else "")
    if isinstance(text, str) and text.strip():
        return json.loads(re.sub(r"^```(?:json)?\s*|\s*```$", "", text.strip(), flags=re.IGNORECASE))
    return {}


def _named(value: Any, *keys: str) -> dict[str, Any]:
    payload = _payload(value)
    for key in keys:
        nested = payload.get(key)
        if isinstance(nested, dict):
            return copy.deepcopy(nested)
    return payload


def _parse_now(value: Any) -> datetime:
    text = str(value or "").strip()
    parsed = datetime.fromisoformat(text.replace("Z", "+00:00")) if text else datetime.now(timezone.utc)
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def _secret(value: Any) -> str:
    getter = getattr(value, "get_secret_value", None)
    return str(getter() if callable(getter) else value or "")


def _get_path(root: Any, path: str) -> Any:
    current = root
    for part in [token for token in re.split(r"\.|\[|\]", path) if token]:
        if isinstance(current, dict):
            current = current.get(part)
        elif isinstance(current, list) and part.isdigit() and int(part) < len(current):
            current = current[int(part)]
        else:
            return None
    return current


def _is_confirmed(root: dict[str, Any], paths: list[str]) -> bool:
    if not paths:
        return False
    for path in paths:
        value = _get_path(root, path)
        if isinstance(value, dict) and value.get("status") == "confirmed" and "value" in value:
            continue
        if isinstance(value, list) and value:
            statuses = [((item.get("provenance") or {}).get("status")) for item in value if isinstance(item, dict)]
            if statuses and all(status == "confirmed" for status in statuses):
                continue
        return False
    return True


def _question_text(gap: dict[str, Any]) -> str:
    code = str(gap.get("reason_code") or "")
    templates = {
        "GOAL_UNKNOWN": "이 업무가 완료됐다고 판단할 수 있는 최종 결과는 무엇인가요?",
        "TRIGGER_UNKNOWN": "이 업무는 어떤 사건, 요청 또는 주기에 시작되나요?",
        "INPUT_CONTRACT_UNKNOWN": "업무에 반드시 들어오는 입력은 무엇이며 형식은 무엇인가요?",
        "OUTPUT_CONTRACT_UNKNOWN": "업무 결과는 무엇이며 누구 또는 어느 시스템에 전달되나요?",
        "PRIMARY_ACTOR_UNKNOWN": "이 업무의 주 수행자와 최종 책임자는 누구인가요?",
        "WRITE_APPROVAL_UNKNOWN": "데이터 저장·수정·발송 전에 담당자 확인이 필요한가요?",
        "SENSITIVE_REVIEW_UNKNOWN": "민감정보 처리 전후에 누가 확인하고 승인해야 하나요?",
        "STEP_SEQUENCE_UNKNOWN": "업무가 시작된 뒤 완료될 때까지의 단계를 순서대로 설명해 주세요.",
        "BRANCH_CONDITION_UNKNOWN": "어떤 조건에서 처리 경로가 나뉘며 각 경로의 결과는 무엇인가요? condition과 branches(2개 이상)를 가진 JSON object로 답해 주세요. 예: {\"condition\":\"오류가 있는가\",\"branches\":[\"예\",\"아니오\"]}",
        "FAILURE_POLICY_UNKNOWN": "조회·처리·전송이 실패하면 재시도, 담당자 전달, 종료 중 어떻게 처리해야 하나요?",
        "SLA_UNKNOWN": "이 업무의 완료 기한 또는 허용 처리 시간은 얼마인가요?",
        "SUCCESS_CRITERIA_UNKNOWN": "결과의 품질과 개선 효과를 어떤 수치나 기준으로 확인할까요?",
        "SCOPE_CONFLICT": "포함 범위와 제외 범위가 겹칩니다. 어느 범위로 확정할까요?",
    }
    return templates.get(code, str(gap.get("message") or "부족한 업무 정보를 알려 주세요."))


def build_clarification_batch(
    work_value: Any,
    completeness_value: Any,
    candidate_questions_value: Any = None,
    *,
    round_number: Any = 1,
    max_questions: Any = 3,
    expiry_minutes: Any = 60,
    now_utc: Any = "",
) -> dict[str, Any]:
    trace_id = f"trace-{uuid.uuid4()}"
    try:
        work = _named(work_value, "work_definition")
        completeness = _named(completeness_value, "completeness")
        candidate_payload = _payload(candidate_questions_value) if candidate_questions_value is not None else {}
        candidates = candidate_payload.get("questions") if isinstance(candidate_payload.get("questions"), list) else []
        supplied_round = int(round_number)
        requested_question_limit = int(max_questions)
        expiry = max(5, min(int(expiry_minutes), 1440))
        now = _parse_now(now_utc)
    except (TypeError, ValueError, json.JSONDecodeError):
        work, completeness, candidates, supplied_round, requested_question_limit, expiry, now = {}, {}, [], -1, DEFAULT_MAX_QUESTIONS_PER_ROUND, 60, datetime.now(timezone.utc)
    processed = work.get("processed_answer_batches") if isinstance(work.get("processed_answer_batches"), list) else []
    processed_batch_ids = {
        str(item.get("batch_id") or "")
        for item in processed[:100]
        if isinstance(item, dict) and str(item.get("batch_id") or "")
    }
    expected_round = min(len(processed_batch_ids) + 1, 4)
    current_round = expected_round if supplied_round == 0 else supplied_round
    maximum_for_round = FINAL_ROUND_MAX_QUESTIONS if current_round == 3 else DEFAULT_MAX_QUESTIONS_PER_ROUND
    question_limit = max(1, min(requested_question_limit, maximum_for_round))
    identity_fields = ("work_definition_id", "tenant_id", "owner_id", "session_id", "revision", "channel_mode")
    missing = [field for field in identity_fields if work.get(field) in (None, "")]
    # Round 4 is a non-interactive post-round gate: it may return
    # READY_FOR_REVIEW, but it must never create a fourth human question batch.
    if missing or current_round not in {1, 2, 3, 4}:
        code = "CLARIFICATION_ROUND_LIMIT" if current_round not in {1, 2, 3, 4} else "CLARIFICATION_INPUT_INVALID"
        return {
            "ok": False,
            "status": "BLOCKED",
            "artifact_refs": [],
            "error": {"code": code, "message": "질문 batch 입력 또는 허용 회차가 유효하지 않습니다.", "retryable": False, "details": {"missing_fields": missing, "round_number": current_round}},
            "resume": None,
            "trace_id": trace_id,
        }
    if current_round != expected_round:
        return {
            "ok": False,
            "status": "BLOCKED",
            "artifact_refs": [],
            "error": {
                "code": "CLARIFICATION_ROUND_SEQUENCE_MISMATCH",
                "message": "질문 회차가 처리 완료된 answer batch 이력과 일치하지 않습니다.",
                "retryable": False,
                "details": {
                    "supplied_round": supplied_round,
                    "expected_round": expected_round,
                    "processed_batch_count": len(processed_batch_ids),
                },
            },
            "resume": None,
            "trace_id": trace_id,
        }
    try:
        work_revision = int(work["revision"])
        completeness_revision = int(completeness.get("revision", -1))
    except (TypeError, ValueError):
        work_revision, completeness_revision = -1, -2
    if completeness.get("work_definition_id") != work.get("work_definition_id") or completeness_revision != work_revision or work_revision < 0:
        return {
            "ok": False,
            "status": "BLOCKED",
            "artifact_refs": [],
            "error": {"code": "CLARIFICATION_REVISION_MISMATCH", "message": "완전성 평가와 WorkDefinition revision이 다릅니다.", "retryable": False, "details": {}},
            "resume": None,
            "trace_id": trace_id,
        }

    gaps = completeness.get("blocking_gaps") if isinstance(completeness.get("blocking_gaps"), list) else []
    gaps = sorted((gap for gap in gaps if isinstance(gap, dict)), key=lambda gap: (PRIORITY_ORDER.get(str(gap.get("priority")), 99), str(gap.get("reason_code"))))
    candidate_by_code = {str(item.get("reason_code")): item for item in candidates if isinstance(item, dict) and item.get("reason_code")}
    questions: list[dict[str, Any]] = []
    seen_paths: set[tuple[str, ...]] = set()
    for gap in gaps:
        paths = [str(path)[:300] for path in gap.get("target_paths", []) if str(path).strip()][:10]
        if not paths or _is_confirmed(work, paths):
            continue
        path_key = tuple(sorted(paths))
        if path_key in seen_paths:
            continue
        model_question = candidate_by_code.get(str(gap.get("reason_code")), {})
        text = str(model_question.get("text") or _question_text(gap)).strip()[:1000]
        if not text:
            continue
        answer_type = str(model_question.get("answer_type") or "text")
        if answer_type not in ALLOWED_ANSWER_TYPES:
            answer_type = "text"
        choices = []
        for choice in model_question.get("choices", []) if isinstance(model_question.get("choices"), list) else []:
            safe = str(choice).strip()[:300]
            if safe and safe not in choices:
                choices.append(safe)
        if answer_type in {"single_choice", "single_choice_with_text", "multi_choice"} and not choices:
            answer_type = "text"
        if str(gap.get("reason_code")) == "BRANCH_CONDITION_UNKNOWN":
            answer_type = "text"
            choices = []
            if "condition" not in text or "branches" not in text:
                text = _question_text(gap)
        material = json.dumps({"work_definition_id": work["work_definition_id"], "revision": work_revision, "round": current_round, "reason": gap.get("reason_code"), "paths": paths}, sort_keys=True, ensure_ascii=False)
        questions.append(
            {
                "question_id": f"q-{hashlib.sha256(material.encode('utf-8')).hexdigest()[:16]}",
                "text": text,
                "target_paths": paths,
                "answer_type": answer_type,
                "choices": choices[:20],
                "required": bool(model_question.get("required", True)),
                "reason_code": str(gap.get("reason_code") or "CLARIFICATION_REQUIRED")[:100],
                "priority": str(gap.get("priority") or "quality"),
            }
        )
        seen_paths.add(path_key)
        if len(questions) >= question_limit:
            break

    if not questions:
        return {
            "ok": True,
            "status": "READY_FOR_REVIEW",
            "artifact_refs": [{"kind": "work_definition", "id": work["work_definition_id"], "revision": work_revision}],
            "clarification_batch": None,
            "trace_id": trace_id,
        }

    if current_round == 4:
        return {
            "ok": False,
            "status": "BLOCKED",
            "artifact_refs": [{"kind": "work_definition", "id": work["work_definition_id"], "revision": work_revision}],
            "clarification_batch": None,
            "error": {
                "code": "CLARIFICATION_ROUND_LIMIT",
                "message": "세 번의 보완 회차 후에도 필수 업무 계약이 남아 있어 자동 승인을 차단했습니다.",
                "retryable": False,
                "details": {"remaining_reason_codes": [question["reason_code"] for question in questions]},
            },
            "resume": None,
            "trace_id": trace_id,
        }

    canonical = json.dumps(questions, sort_keys=True, ensure_ascii=False, separators=(",", ":"))
    batch_material = f"{work['work_definition_id']}|{work['revision']}|{current_round}|{canonical}"
    batch_id = f"qb-{hashlib.sha256(batch_material.encode('utf-8')).hexdigest()[:24]}"
    batch = {
        "schema_version": "clarification-question-batch/v1",
        "batch_id": batch_id,
        "work_definition_id": work["work_definition_id"],
        "tenant_id": work["tenant_id"],
        "owner_id": work["owner_id"],
        "session_id": work["session_id"],
        "channel_mode": work["channel_mode"],
        "revision": work_revision,
        "round_number": current_round,
        "created_at": now.isoformat().replace("+00:00", "Z"),
        "expires_at": (now + timedelta(minutes=expiry)).isoformat().replace("+00:00", "Z"),
        "status": "WAITING_ANSWER",
        "questions": questions,
    }
    return {
        "ok": True,
        "status": "WAITING_ANSWER",
        "artifact_refs": [{"kind": "clarification_batch", "id": batch_id}],
        "clarification_batch": batch,
        "trace_id": trace_id,
    }


def _initial_work_document(work_value: Any, batch: dict[str, Any]) -> dict[str, Any]:
    """Build the first durable WorkDefinition required by the Answer Form API.

    This is intentionally limited to round 1.  Later rounds must never
    overwrite a WorkDefinition that may already contain answer provenance and
    a newer semantic revision.
    """
    work = _named(work_value, "work_definition")
    required = ("work_definition_id", "tenant_id", "owner_id", "session_id", "channel_mode", "revision")
    missing = [name for name in required if work.get(name) in (None, "")]
    if missing:
        raise ValueError("INITIAL_WORK_INPUT_INVALID")
    for name in ("work_definition_id", "tenant_id", "owner_id", "session_id", "channel_mode", "revision"):
        if str(work.get(name)) != str(batch.get(name)):
            raise ValueError("INITIAL_WORK_BATCH_IDENTITY_MISMATCH")
    if str(work.get("channel_mode")) != "native_hitl":
        raise ValueError("INITIAL_WORK_CHANNEL_INVALID")
    try:
        revision = int(work.get("revision"))
    except (TypeError, ValueError) as exc:
        raise ValueError("INITIAL_WORK_REVISION_INVALID") from exc
    if revision != 0 or int(batch.get("round_number", 0)) != 1:
        raise ValueError("INITIAL_WORK_REVISION_INVALID")
    identity_material = f"{work['tenant_id']}|{work['work_definition_id']}"
    document = copy.deepcopy(work)
    document.pop("_id", None)
    document.pop("pending_action", None)
    document.pop("mutation_receipts", None)
    document.pop("last_event", None)
    document["_id"] = "work-definition:" + hashlib.sha256(identity_material.encode("utf-8")).hexdigest()
    document["revision"] = 0
    document["status"] = "WAITING_ANSWER"
    document["approved_hash"] = None
    document["processed_answer_batches"] = []
    created_at = _parse_now(batch.get("created_at"))
    document["created_at"] = created_at
    document["updated_at"] = created_at
    serialized = json.dumps(document, ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=str)
    if len(serialized.encode("utf-8")) > MAX_INITIAL_WORK_DOCUMENT_BYTES:
        raise ValueError("INITIAL_WORK_DOCUMENT_TOO_LARGE")
    return document


def _ensure_initial_work_definition(definitions: Any, work_value: Any, batch: dict[str, Any]) -> dict[str, Any]:
    """Idempotently insert the round-1 record without clobbering later work."""
    document = _initial_work_document(work_value, batch)
    identity = {"tenant_id": document["tenant_id"], "work_definition_id": document["work_definition_id"]}
    existing = definitions.find_one(identity)
    if existing is not None:
        for name in ("tenant_id", "work_definition_id", "owner_id", "session_id", "channel_mode"):
            if str(existing.get(name) or "") != str(document.get(name) or ""):
                raise ValueError("INITIAL_WORK_IDENTITY_CONFLICT")
        return {
            "initialized": True,
            "idempotent_replay": True,
            "work_definition_id": document["work_definition_id"],
            "revision": int(existing.get("revision", 0)),
        }
    try:
        definitions.insert_one(document)
    except DuplicateKeyError:
        existing = definitions.find_one(identity)
        if existing is None:
            raise
        for name in ("tenant_id", "work_definition_id", "owner_id", "session_id", "channel_mode"):
            if str(existing.get(name) or "") != str(document.get(name) or ""):
                raise ValueError("INITIAL_WORK_IDENTITY_CONFLICT")
        return {
            "initialized": True,
            "idempotent_replay": True,
            "work_definition_id": document["work_definition_id"],
            "revision": int(existing.get("revision", 0)),
        }
    return {
        "initialized": True,
        "idempotent_replay": False,
        "work_definition_id": document["work_definition_id"],
        "revision": 0,
    }


def persist_clarification_batch(
    result: dict[str, Any],
    *,
    work_value: Any = None,
    mongodb_uri: Any,
    mongo_database: Any,
    collection_name: Any = "clarification_batches",
    work_collection: Any = "work_definitions",
    timeout_ms: Any = 5000,
    client_factory: Any = MongoClient,
) -> dict[str, Any]:
    """Persist one immutable question contract; Answer Form may add answers later."""
    if not result.get("ok") or result.get("clarification_batch") is None:
        return result
    uri = _secret(mongodb_uri)
    database_name = str(mongo_database or "").strip()[:200]
    collection = str(collection_name or "clarification_batches").strip()[:200]
    work_name = str(work_collection or "work_definitions").strip()[:200]
    try:
        timeout = max(1000, min(int(timeout_ms), 30_000))
    except (TypeError, ValueError):
        timeout = 5000
    if (
        not uri
        or not database_name
        or not re.fullmatch(r"[A-Za-z0-9_.-]{1,200}", collection)
        or not re.fullmatch(r"[A-Za-z0-9_.-]{1,200}", work_name)
    ):
        failed = copy.deepcopy(result)
        failed.update({"ok": False, "status": "BLOCKED", "error": {"code": "CLARIFICATION_STORE_CONFIG_MISSING", "message": "질문 batch를 저장할 production MongoDB 설정이 필요합니다.", "retryable": False, "details": {}}, "resume": None})
        return failed
    batch = copy.deepcopy(result["clarification_batch"])
    contract_material = json.dumps({key: batch.get(key) for key in ("batch_id", "work_definition_id", "tenant_id", "owner_id", "session_id", "channel_mode", "revision", "round_number", "questions")}, sort_keys=True, ensure_ascii=False, separators=(",", ":"))
    contract_hash = hashlib.sha256(contract_material.encode("utf-8")).hexdigest()
    document = copy.deepcopy(batch)
    document["_id"] = "clarification-batch:" + hashlib.sha256(f"{batch['tenant_id']}|{batch['batch_id']}".encode("utf-8")).hexdigest()
    document["contract_sha256"] = contract_hash
    document["created_at"] = _parse_now(batch["created_at"])
    document["expires_at"] = _parse_now(batch["expires_at"])
    document["answers"] = None
    document["answer_idempotency_key"] = None
    document["answered_at"] = None
    client = None
    try:
        client = client_factory(uri, serverSelectionTimeoutMS=timeout, connectTimeoutMS=timeout, socketTimeoutMS=timeout, retryWrites=True)
        client.admin.command("ping")
        database = client[database_name]
        batches = database[collection]
        existing = batches.find_one({"_id": document["_id"]})
        batch_replay = False
        if existing is not None:
            if str(existing.get("contract_sha256")) != contract_hash:
                failed = copy.deepcopy(result)
                failed.update({"ok": False, "status": "BLOCKED", "error": {"code": "CLARIFICATION_BATCH_CONFLICT", "message": "같은 batch ID에 다른 질문 계약이 이미 저장되어 있습니다.", "retryable": False, "details": {}}, "resume": None})
                return failed
            batch_replay = True
        else:
            try:
                batches.insert_one(document)
            except DuplicateKeyError:
                existing = batches.find_one({"_id": document["_id"]})
                if existing is None or str(existing.get("contract_sha256")) != contract_hash:
                    raise
                batch_replay = True
        initial_work_result = None
        if int(batch.get("round_number", 0)) == 1:
            initial_work_result = _ensure_initial_work_definition(database[work_name], work_value, batch)
        persisted = copy.deepcopy(result)
        persisted["store_result"] = {
            "persisted": True,
            "idempotent_replay": batch_replay,
            "contract_sha256": contract_hash,
            "initial_work_definition": initial_work_result,
        }
        return persisted
    except ValueError as exc:
        code = str(exc)
        messages = {
            "INITIAL_WORK_INPUT_INVALID": "첫 질문 batch에는 초기 WorkDefinition 입력이 필요합니다.",
            "INITIAL_WORK_BATCH_IDENTITY_MISMATCH": "초기 WorkDefinition과 질문 batch의 식별자 또는 revision이 다릅니다.",
            "INITIAL_WORK_CHANNEL_INVALID": "초기 WorkDefinition은 native_hitl channel이어야 합니다.",
            "INITIAL_WORK_REVISION_INVALID": "초기 WorkDefinition은 revision 0의 1차 질문에서만 생성할 수 있습니다.",
            "INITIAL_WORK_DOCUMENT_TOO_LARGE": "초기 WorkDefinition이 허용 크기를 초과합니다.",
            "INITIAL_WORK_IDENTITY_CONFLICT": "같은 WorkDefinition ID에 다른 owner, session 또는 channel이 이미 저장되어 있습니다.",
        }
        failed = copy.deepcopy(result)
        failed.update({"ok": False, "status": "BLOCKED", "error": {"code": code or "INITIAL_WORK_STORE_FAILED", "message": messages.get(code, "초기 WorkDefinition을 안전하게 준비하지 못했습니다."), "retryable": False, "details": {}}, "resume": None})
        return failed
    except PyMongoError as exc:
        failed = copy.deepcopy(result)
        failed.update({"ok": False, "status": "BLOCKED", "error": {"code": "CLARIFICATION_STORE_FAILED", "message": "질문 batch를 MongoDB에 저장하지 못했습니다.", "retryable": True, "details": {"exception_type": type(exc).__name__}}, "resume": None})
        return failed
    finally:
        if client is not None:
            client.close()


class ClarificationBatchBuilderComponent(Component):
    display_name = "13 재질문 Batch 생성"
    description = "완전성 gap과 질문 후보를 검증해 confirmed 항목을 제외한 질문 batch를 만듭니다. 1·2차는 최대 3개, 마지막 3차는 최대 4개 질문이며 1차에는 초기 WorkDefinition도 idempotent하게 준비합니다."
    icon = "MessageCircleQuestion"
    name = "ClarificationBatchBuilder"

    inputs = [
        DataInput(name="work_definition", display_name="WorkDefinition", input_types=["Data", "JSON"], required=True),
        DataInput(name="completeness", display_name="완전성 평가", input_types=["Data", "JSON"], required=True),
        DataInput(name="candidate_questions", display_name="모델 질문 후보", input_types=["Data", "Message", "JSON"], required=False),
        IntInput(name="round_number", display_name="질문 회차(0=이력에서 자동 계산)", value=0),
        IntInput(name="max_questions", display_name="회차당 최대 질문 (3차 최대 4개)", value=3, advanced=True),
        IntInput(name="expiry_minutes", display_name="응답 만료(분)", value=60, advanced=True),
        MessageTextInput(name="now_utc", display_name="기준 시각(ISO-8601)", value="", advanced=True),
        SecretStrInput(
            name="mongodb_uri",
            display_name="MongoDB URI (환경 설정)",
            required=True,
            info="F10의 질문 Batch 저장에 필요한 환경 Secret입니다. 세 회차에 같은 URI를 설정합니다.",
        ),
        MessageTextInput(
            name="mongo_database",
            display_name="MongoDB Database (환경 설정)",
            value="business_work_design",
            required=True,
            info="F10의 질문 Batch 저장에 사용하는 Database입니다. 기본값을 유지합니다.",
        ),
        MessageTextInput(name="collection_name", display_name="질문 Batch Collection", value="clarification_batches", advanced=True),
        MessageTextInput(name="work_collection", display_name="WorkDefinition Collection", value="work_definitions", advanced=True),
        IntInput(name="timeout_ms", display_name="MongoDB Timeout(ms)", value=5000, advanced=True),
    ]
    outputs = [
        Output(name="clarification_batch", display_name="재질문 Batch", method="build_batch", types=["Data"]),
        Output(name="waiting_path", display_name="답변 대기", method="route_batch", types=["Data"], group_outputs=True),
        Output(name="review_path", display_name="바로 검토", method="route_batch", types=["Data"], group_outputs=True),
        Output(name="blocked_path", display_name="질문 생성 차단", method="route_batch", types=["Data"], group_outputs=True),
        Output(name="question_message", display_name="HITL 질문 안내", method="build_question_message", types=["Message"]),
    ]

    def _result(self) -> dict[str, Any]:
        """Persist a question contract only once even when several outputs run."""

        result = getattr(self, "_batch_result", None)
        if isinstance(result, dict):
            return result
        built = build_clarification_batch(
            getattr(self, "work_definition", None),
            getattr(self, "completeness", None),
            getattr(self, "candidate_questions", None),
            round_number=getattr(self, "round_number", 1),
            max_questions=getattr(self, "max_questions", 3),
            expiry_minutes=getattr(self, "expiry_minutes", 60),
            now_utc=getattr(self, "now_utc", ""),
        )
        result = persist_clarification_batch(
            built,
            work_value=getattr(self, "work_definition", None),
            mongodb_uri=getattr(self, "mongodb_uri", ""),
            mongo_database=getattr(self, "mongo_database", ""),
            collection_name=getattr(self, "collection_name", "clarification_batches"),
            work_collection=getattr(self, "work_collection", "work_definitions"),
            timeout_ms=getattr(self, "timeout_ms", 5000),
            client_factory=MongoClient,
        )
        # A no-question result is a valid direct review exit.  Preserve the
        # canonical work beside the batch envelope so the compact F10 Joiner
        # can route it without a duplicate bypass edge.
        try:
            work = _named(getattr(self, "work_definition", None), "work_definition")
        except (TypeError, ValueError, json.JSONDecodeError):
            work = {}
        if isinstance(work, dict) and work and "work_definition" not in result:
            result = copy.deepcopy(result)
            result["work_definition"] = work
        self._batch_result = result
        self.status = {
            "ok": result["ok"],
            "status": result["status"],
            "question_count": len((result.get("clarification_batch") or {}).get("questions", [])),
        }
        return result

    def build_batch(self) -> Data:
        return Data(data=self._result())

    def _component_id(self) -> str:
        """Return the graph vertex id used by Langflow branch exclusion."""

        return str(getattr(self, "_id", "") or self.name)[:200]

    def _select_output_route(self, selected: str) -> None:
        """Stop and persistently exclude non-selected batch routes."""

        output_names = ("waiting_path", "review_path", "blocked_path")
        if selected not in output_names:
            for output_name in output_names:
                self.stop(output_name)
            self.stop("question_message")
            return

        non_selected = [output_name for output_name in output_names if output_name != selected]
        for output_name in non_selected:
            self.stop(output_name)
        if selected != "waiting_path":
            self.stop("question_message")
            non_selected.append("question_message")

        graph = getattr(self, "graph", None)
        exclude = getattr(graph, "exclude_branches_conditionally", None) if graph is not None else None
        if callable(exclude):
            exclude(self._component_id(), non_selected)

    def _is_nonselected_group_output(self, selected: str) -> bool:
        current_output = str(getattr(self, "_current_output", "") or "")
        return bool(
            current_output
            and selected in {"waiting_path", "review_path", "blocked_path"}
            and current_output in {"waiting_path", "review_path", "blocked_path"}
            and current_output != selected
        )

    def route_batch(self) -> Data:
        result = self._result()
        if result.get("ok") is not True:
            selected = "blocked_path"
        elif result.get("status") == "WAITING_ANSWER":
            selected = "waiting_path"
        elif result.get("status") == "READY_FOR_REVIEW":
            selected = "review_path"
        else:
            selected = "blocked_path"
        self._select_output_route(selected)
        if self._is_nonselected_group_output(selected):
            return Data(data={})
        return Data(data=result)

    def build_question_message(self) -> Message:
        result = self._result()
        batch = result.get("clarification_batch")
        if result.get("ok") is not True or result.get("status") != "WAITING_ANSWER" or not isinstance(batch, dict):
            self.stop("question_message")
            return Message(text="")
        questions = batch.get("questions") if isinstance(batch.get("questions"), list) else []
        lines = [f"업무 정의를 위해 {batch.get('round_number', '?')}차 보완이 필요합니다."]
        for index, question in enumerate(questions[:FINAL_ROUND_MAX_QUESTIONS], start=1):
            if not isinstance(question, dict):
                continue
            text = str(question.get("text") or "").strip()[:1000]
            if not text:
                continue
            suffix = ""
            choices = [str(choice).strip()[:200] for choice in question.get("choices", []) if str(choice).strip()]
            if choices:
                suffix = " 선택지: " + " / ".join(choices[:20])
            lines.append(f"{index}. {text}{suffix}")
        lines.extend(
            [
                "",
                "답변은 Answer Form에서 이 질문 batch에 저장한 뒤 Submit Answers를 선택해 주세요.",
                "답변을 중단하려면 Cancel을 선택할 수 있습니다.",
            ]
        )
        return Message(text="\n".join(lines)[:8_000])

from __future__ import annotations

"""Langflow 1.11.0-compatible F10 clarification choice gate.

The deployed Human Input implementation supports durable *choices*, not
dynamic text form fields.  This standalone component therefore pauses only
for the human's next action:

* answer in the normal Playground Chat Input;
* skip additional input; or
* cancel.

The selected ``continue_to_chat`` branch returns a copyable numbered answer
template.  A separate standalone parser reads the later Chat Input message
and turns it into the existing F10 answer contract.  No browser extension,
local-module import, or Flow/API call is required here.
"""

import copy
import hashlib
import json
import math
import re
import uuid
from datetime import datetime, timezone
from typing import Any

from lfx.custom import Component
from lfx.io import DataInput, Output
from lfx.schema import Data


HUMAN_INPUT_REQUIRED = "human_input_required"
KIND_NODE_INPUT = "node_input"
CONTINUE_ACTION = "continue_to_chat"
# Retained as the stable answer-commit action.  It is emitted by the
# playground-chat parser, not selected on this choice-only HITL card.
SUBMIT_ACTION = "submit_answers"
SKIP_ACTION = "skip_additional_input"
CANCEL_ACTION = "cancel"
# Rounds 1 and 2 ask at most three questions.  The third and final card may
# ask a fourth question so a ten-gap definition still fits the three-round
# limit.  The person answers these through the numbered Chat Input template.
MAX_QUESTIONS = 4
MAX_FREE_TEXT_CHARS = 16_000
MAX_ANSWER_VALUE_BYTES = 64 * 1024
ALLOWED_ANSWER_TYPES = {
    "text",
    "single_choice",
    "single_choice_with_text",
    "multi_choice",
    "boolean",
    "number",
}


def _payload(value: Any) -> dict[str, Any]:
    """Read a Data/dict/JSON value without relying on another component."""

    if isinstance(value, dict):
        return copy.deepcopy(value)
    data = getattr(value, "data", None)
    if isinstance(data, dict):
        return copy.deepcopy(data)
    text = getattr(value, "text", value if isinstance(value, str) else "")
    if isinstance(text, str) and text.strip():
        parsed = json.loads(re.sub(r"^```(?:json)?\s*|\s*```$", "", text.strip(), flags=re.IGNORECASE))
        return copy.deepcopy(parsed) if isinstance(parsed, dict) else {}
    return {}


def _batch(value: Any) -> dict[str, Any]:
    """Accept either F13's result envelope or its nested batch itself."""

    payload = _payload(value)
    nested = payload.get("clarification_batch")
    return copy.deepcopy(nested) if isinstance(nested, dict) else payload


def _utc_now() -> datetime:
    return datetime.now(timezone.utc)


def _iso(value: datetime) -> str:
    return value.astimezone(timezone.utc).isoformat().replace("+00:00", "Z")


def _canonical(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=str)


def _bounded_text(value: Any, maximum: int) -> str:
    return str(value or "").strip()[:maximum]


def _failure(code: str, message: str, trace_id: str, details: dict[str, Any] | None = None) -> dict[str, Any]:
    return {
        "ok": False,
        "status": "BLOCKED",
        "route": "blocked_path",
        "artifact_refs": [],
        "error": {
            "code": code,
            "message": message,
            "retryable": False,
            "details": details or {},
        },
        "resume": None,
        "trace_id": trace_id,
    }


def _safe_field_name(index: int) -> str:
    """A browser-safe, stable key; it deliberately never contains question_id."""

    return f"answer_{index:02d}"


def _question_mappings(batch: dict[str, Any]) -> list[dict[str, Any]]:
    """Validate the batch and bind each original question id to a safe field key."""

    required_identity = (
        "batch_id",
        "work_definition_id",
        "tenant_id",
        "owner_id",
        "session_id",
        "channel_mode",
        "revision",
        "round_number",
    )
    missing_identity = [name for name in required_identity if batch.get(name) in (None, "")]
    if missing_identity:
        raise ValueError("CLARIFICATION_BATCH_IDENTITY_INVALID")
    if str(batch.get("channel_mode") or "") != "native_hitl":
        raise ValueError("CLARIFICATION_BATCH_CHANNEL_INVALID")
    if str(batch.get("status") or "") != "WAITING_ANSWER":
        raise ValueError("CLARIFICATION_BATCH_STATE_INVALID")
    try:
        if int(batch.get("revision")) < 0 or int(batch.get("round_number")) not in {1, 2, 3}:
            raise ValueError("CLARIFICATION_BATCH_IDENTITY_INVALID")
    except (TypeError, ValueError) as exc:
        if str(exc) == "CLARIFICATION_BATCH_IDENTITY_INVALID":
            raise
        raise ValueError("CLARIFICATION_BATCH_IDENTITY_INVALID") from exc

    questions = batch.get("questions")
    if not isinstance(questions, list) or not 1 <= len(questions) <= MAX_QUESTIONS:
        raise ValueError("CLARIFICATION_QUESTION_CONTRACT_INVALID")
    mappings: list[dict[str, Any]] = []
    seen_ids: set[str] = set()
    for index, raw_question in enumerate(questions, start=1):
        if not isinstance(raw_question, dict):
            raise ValueError("CLARIFICATION_QUESTION_CONTRACT_INVALID")
        question_id = _bounded_text(raw_question.get("question_id"), 200)
        question_text = _bounded_text(raw_question.get("text"), 4_000)
        if not question_id or not question_text or question_id in seen_ids:
            raise ValueError("CLARIFICATION_QUESTION_CONTRACT_INVALID")
        answer_type = str(raw_question.get("answer_type") or "text")
        if answer_type not in ALLOWED_ANSWER_TYPES:
            raise ValueError("CLARIFICATION_QUESTION_TYPE_INVALID")
        raw_choices = raw_question.get("choices") if isinstance(raw_question.get("choices"), list) else []
        choices = []
        for choice in raw_choices[:20]:
            if not isinstance(choice, str):
                raise ValueError("CLARIFICATION_QUESTION_CHOICES_INVALID")
            cleaned = choice.strip()[:300]
            if cleaned and cleaned not in choices:
                choices.append(cleaned)
        if answer_type in {"single_choice", "single_choice_with_text", "multi_choice"} and not choices:
            raise ValueError("CLARIFICATION_QUESTION_CHOICES_INVALID")
        mappings.append(
            {
                "field_name": _safe_field_name(index),
                "question_id": question_id,
                "question": copy.deepcopy(raw_question),
                "required": bool(raw_question.get("required", True)),
                "answer_type": answer_type,
                "choices": choices,
            }
        )
        seen_ids.add(question_id)
    return mappings


def _field_instruction(mapping: dict[str, Any]) -> str:
    """Show type-specific guidance for the numbered Chat Input reply."""

    answer_type = mapping["answer_type"]
    choices = mapping["choices"]
    if answer_type == "single_choice":
        return "선택지 중 하나를 정확히 입력: " + " / ".join(choices)
    if answer_type == "single_choice_with_text":
        return (
            "선택지는 "
            + " / ".join(choices)
            + ". 선택지에 없으면 `기타: 설명` 형식으로 입력"
        )
    if answer_type == "multi_choice":
        return "복수 선택은 쉼표로 구분해 입력: " + " / ".join(choices)
    if answer_type == "boolean":
        return "true/false 또는 예/아니오로 입력"
    if answer_type == "number":
        return "숫자로 입력"
    return "자유롭게 서술해 입력"


def build_pause_request(batch_value: Any, *, component_id: Any = "F10ClarificationAnswerGate", run_id: Any = "") -> dict[str, Any]:
    """Build the choice-only ``node_input`` contract supported by 1.11.0."""

    batch = _batch(batch_value)
    mappings = _question_mappings(batch)
    component = _bounded_text(component_id, 200) or "F10ClarificationAnswerGate"
    run = _bounded_text(run_id, 200) or "run"
    batch_id = _bounded_text(batch.get("batch_id"), 200)
    # Langflow 1.11.0's native Human Input resumes a vertex by the exact
    # ``<vertex_id>:<run_id>`` key.  The question batch belongs in the pause
    # payload, not in this key; adding a suffix can leave the gate cached in
    # its paused state when the server injects the resumed decision.
    request_id = f"{component}:{run}"
    lines = [
        f"업무 정의를 위해 {batch.get('round_number')}차 보완이 필요합니다.",
        "이 운영 환경에서는 질문 카드 안에 입력칸이 표시되지 않습니다.",
        "아래 질문을 확인한 뒤 **답변 입력하기**를 선택하면, 다음 화면에서 Playground 채팅창에 `1번: ...` 형식으로 답할 수 있습니다.",
        "추가 정보가 없으면 추가 입력 건너뛰기를 선택할 수 있습니다. 이 경우 답변하지 않은 항목은 미확정으로 기록된 채 검토 단계로 넘어갑니다.",
    ]
    for index, mapping in enumerate(mappings, start=1):
        question = mapping["question"]
        lines.extend(
            [
                "",
                f"{index}. {_bounded_text(question.get('text'), 4_000)}",
                f"   번호형 답변: {index}번: ... — {_field_instruction(mapping)}",
            ]
        )
    return {
        "request_id": request_id,
        "kind": KIND_NODE_INPUT,
        "prompt": "\n".join(lines)[:16_000],
        "options": [
            {"action_id": CONTINUE_ACTION, "label": "답변 입력하기"},
            {"action_id": SKIP_ACTION, "label": "추가 입력 건너뛰기"},
            {"action_id": CANCEL_ACTION, "label": "Cancel"},
        ],
        "allowed_decisions": [CONTINUE_ACTION, SKIP_ACTION, CANCEL_ACTION],
        "batch_id": batch_id,
        "field_mappings": [
            {"field_name": item["field_name"], "question_id": item["question_id"]}
            for item in mappings
        ],
        "paused_at": _iso(_utc_now()),
    }


def _is_blank(value: Any) -> bool:
    return value is None or value == [] or (isinstance(value, str) and not value.strip())


def _parse_json_object(value: str) -> dict[str, Any] | None:
    try:
        parsed = json.loads(value)
    except (TypeError, json.JSONDecodeError):
        return None
    return parsed if isinstance(parsed, dict) else None


def _parse_json_list(value: str) -> list[Any] | None:
    try:
        parsed = json.loads(value)
    except (TypeError, json.JSONDecodeError):
        return None
    return parsed if isinstance(parsed, list) else None


def _normalize_answer(question: dict[str, Any], raw_value: Any) -> Any:
    """Convert the text-only native form values to the canonical answer type."""

    answer_type = str(question.get("answer_type") or "text")
    if answer_type not in ALLOWED_ANSWER_TYPES:
        raise ValueError("ANSWER_VALUE_TYPE_INVALID")
    required = bool(question.get("required", True))
    if _is_blank(raw_value):
        if required:
            raise ValueError("ANSWER_REQUIRED_VALUE_MISSING")
        return None
    choices = [str(choice).strip() for choice in (question.get("choices") or []) if isinstance(choice, str) and str(choice).strip()]

    if answer_type == "text":
        if not isinstance(raw_value, str) or len(raw_value) > MAX_FREE_TEXT_CHARS:
            raise ValueError("ANSWER_VALUE_TYPE_INVALID")
        normalized: Any = raw_value.strip()
    elif answer_type == "single_choice":
        if not isinstance(raw_value, str) or raw_value.strip() not in choices:
            raise ValueError("ANSWER_CHOICE_INVALID")
        normalized = raw_value.strip()
    elif answer_type == "single_choice_with_text":
        candidate = raw_value
        if isinstance(candidate, str):
            candidate = candidate.strip()
            if candidate in choices:
                normalized = {"choice": candidate, "text": ""}
            else:
                candidate = _parse_json_object(candidate)
                if candidate is None:
                    raise ValueError("ANSWER_VALUE_TYPE_INVALID")
                normalized = None
        else:
            normalized = None
        if normalized is None:
            if not isinstance(candidate, dict) or set(candidate) - {"choice", "text"}:
                raise ValueError("ANSWER_VALUE_TYPE_INVALID")
            choice = candidate.get("choice")
            detail = candidate.get("text", "")
            if not isinstance(choice, str) or not isinstance(detail, str) or len(detail) > MAX_FREE_TEXT_CHARS:
                raise ValueError("ANSWER_VALUE_TYPE_INVALID")
            if choice == "__other__":
                if not detail.strip():
                    raise ValueError("ANSWER_REQUIRED_VALUE_MISSING")
            elif choice not in choices:
                raise ValueError("ANSWER_CHOICE_INVALID")
            normalized = {"choice": choice, "text": detail.strip()}
    elif answer_type == "multi_choice":
        candidate = raw_value
        if isinstance(candidate, str):
            text = candidate.strip()
            parsed = _parse_json_list(text) if text.startswith("[") else None
            candidate = parsed if parsed is not None else [part.strip() for part in re.split(r"[,\n]", text) if part.strip()]
        if not isinstance(candidate, list) or not candidate:
            raise ValueError("ANSWER_CHOICE_INVALID")
        if any(not isinstance(item, str) or item.strip() not in choices for item in candidate):
            raise ValueError("ANSWER_CHOICE_INVALID")
        normalized = list(dict.fromkeys(item.strip() for item in candidate))
    elif answer_type == "boolean":
        if isinstance(raw_value, bool):
            normalized = raw_value
        elif isinstance(raw_value, str):
            text = raw_value.strip().lower()
            if text in {"true", "1", "yes", "y", "예", "네"}:
                normalized = True
            elif text in {"false", "0", "no", "n", "아니오", "아니요"}:
                normalized = False
            else:
                raise ValueError("ANSWER_VALUE_TYPE_INVALID")
        else:
            raise ValueError("ANSWER_VALUE_TYPE_INVALID")
    else:  # number
        if isinstance(raw_value, bool):
            raise ValueError("ANSWER_VALUE_TYPE_INVALID")
        try:
            numeric = float(raw_value.strip() if isinstance(raw_value, str) else raw_value)
        except (TypeError, ValueError):
            raise ValueError("ANSWER_VALUE_TYPE_INVALID") from None
        if not math.isfinite(numeric) or abs(numeric) > 1e15:
            raise ValueError("ANSWER_VALUE_TYPE_INVALID")
        normalized = int(numeric) if numeric.is_integer() else numeric
    if len(_canonical(normalized).encode("utf-8")) > MAX_ANSWER_VALUE_BYTES:
        raise ValueError("ANSWER_VALUE_TOO_LARGE")
    return normalized


def build_resumed_submission(
    batch_value: Any,
    decision: Any,
    *,
    request_id: Any = "",
    now_utc: Any = "",
) -> dict[str, Any]:
    """Map one resumed native decision to an F10 answer/cancel result envelope."""

    trace_id = f"trace-{uuid.uuid4()}"
    try:
        batch = _batch(batch_value)
        mappings = _question_mappings(batch)
    except (TypeError, ValueError, json.JSONDecodeError) as exc:
        code = str(exc) or "CLARIFICATION_BATCH_INVALID"
        messages = {
            "CLARIFICATION_BATCH_IDENTITY_INVALID": "질문 batch의 업무 식별자 또는 회차 정보가 유효하지 않습니다.",
            "CLARIFICATION_BATCH_CHANNEL_INVALID": "이 HITL 게이트는 native_hitl 질문 batch만 처리합니다.",
            "CLARIFICATION_BATCH_STATE_INVALID": "답변을 기다리는 상태의 질문 batch만 Playground HITL로 열 수 있습니다.",
            "CLARIFICATION_QUESTION_CONTRACT_INVALID": "질문 batch의 질문 수, 질문 ID 또는 질문 내용이 유효하지 않습니다.",
            "CLARIFICATION_QUESTION_TYPE_INVALID": "질문의 answer_type이 지원 범위를 벗어났습니다.",
            "CLARIFICATION_QUESTION_CHOICES_INVALID": "선택형 질문의 선택지가 유효하지 않습니다.",
        }
        return _failure(code, messages.get(code, "질문 batch를 읽을 수 없습니다."), trace_id)
    if not isinstance(decision, dict):
        return _failure("HUMAN_DECISION_INVALID", "재개된 Human Input 결정값이 object가 아닙니다.", trace_id)
    action_id = str(decision.get("action_id") or "").strip()
    if action_id not in {CONTINUE_ACTION, SUBMIT_ACTION, SKIP_ACTION, CANCEL_ACTION}:
        return _failure("HUMAN_DECISION_INVALID", "답변 입력하기, 추가 입력 건너뛰기 또는 Cancel 중 하나를 선택해야 합니다.", trace_id)
    if action_id == CONTINUE_ACTION:
        lines = [
            "아래 질문을 확인한 뒤, 맨 아래 **복사용 답변 양식**만 Playground 하단 채팅창에 붙여 넣어 답해 주세요.",
            "질문 묶음 ID는 여러 작업이 동시에 열려 있을 때만 필요합니다. 그대로 복사해도 됩니다.",
            "",
            "[질문과 입력 안내]",
        ]
        for index, mapping in enumerate(mappings, start=1):
            question = mapping["question"]
            lines.extend(
                [
                    "",
                    f"{index}. {_bounded_text(question.get('text'), 4_000)}",
                    f"   입력 안내: {_field_instruction(mapping)}",
                ]
            )
        lines.extend(
            [
                "",
                "[복사용 답변 양식 — 아래 블록만 복사해 대괄호 안을 바꾸세요]",
                f"질문 묶음: {batch['batch_id']}",
                *[f"{index}번: [{index}번 답변을 입력하세요]" for index in range(1, len(mappings) + 1)],
                "",
                "모든 필수 질문에 답한 뒤 한 번에 전송해 주세요.",
                "형식 오류가 표시된 경우에는 같은 질문 묶음 ID와 번호로 고쳐서 다시 전송해 주세요.",
            ]
        )
        return {
            "ok": True,
            "status": "WAITING_CHAT_ANSWER",
            "route": "branch_continue_chat",
            "artifact_refs": [{"kind": "clarification_batch", "id": batch["batch_id"]}],
            "clarification_batch": copy.deepcopy(batch),
            "answer_submission": None,
            "chat_answer_guidance": "\n".join(lines)[:16_000],
            "chat_request_id": str(request_id or ""),
            "human_decision": {"action_id": CONTINUE_ACTION, "values": {}},
            "trace_id": trace_id,
        }
    if action_id == CANCEL_ACTION:
        return {
            "ok": True,
            "status": "CANCELLED",
            "route": "branch_cancel",
            "artifact_refs": [{"kind": "clarification_batch", "id": batch["batch_id"]}],
            "clarification_batch": copy.deepcopy(batch),
            "human_decision": {"action_id": CANCEL_ACTION, "values": {}},
            "answer_submission": None,
            "trace_id": trace_id,
        }
    if action_id == SKIP_ACTION:
        try:
            revision = int(batch["revision"])
            round_number = int(batch["round_number"])
        except (TypeError, ValueError):
            return _failure("CLARIFICATION_BATCH_IDENTITY_INVALID", "질문 batch revision 또는 회차가 유효하지 않습니다.", trace_id)
        now = _utc_now()
        if str(now_utc or "").strip():
            try:
                parsed = datetime.fromisoformat(str(now_utc).replace("Z", "+00:00"))
                now = parsed.replace(tzinfo=timezone.utc) if parsed.tzinfo is None else parsed.astimezone(timezone.utc)
            except ValueError:
                return _failure("SUBMITTED_AT_INVALID", "제출 시각은 ISO-8601 형식이어야 합니다.", trace_id)
        identity = {
            "batch_id": batch["batch_id"],
            "work_definition_id": batch["work_definition_id"],
            "tenant_id": batch["tenant_id"],
            "owner_id": batch["owner_id"],
            "session_id": batch["session_id"],
            "channel_mode": batch["channel_mode"],
            "revision": revision,
            "round_number": round_number,
        }
        skipped_question_ids = [item["question_id"] for item in mappings]
        idempotency_material = _canonical(
            {
                "request_id": str(request_id or ""),
                **identity,
                "action_id": SKIP_ACTION,
                "skipped_question_ids": skipped_question_ids,
            }
        )
        idempotency_key = "hitl-skip-" + hashlib.sha256(idempotency_material.encode("utf-8")).hexdigest()[:32]
        skip_id = "skip-" + hashlib.sha256((idempotency_material + "|skip").encode("utf-8")).hexdigest()[:24]
        skip_submission = {
            "schema_version": "native-clarification-skip-submission/v1",
            "skip_id": skip_id,
            **identity,
            "request_id": str(request_id or ""),
            "action_id": SKIP_ACTION,
            "skipped_question_ids": skipped_question_ids,
            "idempotency_key": idempotency_key,
            "skipped_at": _iso(now),
            "source": "langflow_native_node_input",
        }
        return {
            "ok": True,
            "status": "CLARIFICATION_SKIPPED",
            "route": "branch_skip_additional_input",
            "artifact_refs": [
                {"kind": "clarification_batch", "id": batch["batch_id"]},
                {"kind": "clarification_skip", "id": skip_id},
            ],
            "clarification_batch": copy.deepcopy(batch),
            "skip_submission": skip_submission,
            "answer_submission": None,
            "human_decision": {"action_id": SKIP_ACTION, "values": {}},
            "trace_id": trace_id,
        }

    values = decision.get("values")
    if not isinstance(values, dict):
        return _failure("HUMAN_DECISION_VALUES_INVALID", "제출된 답변 값이 object 형식이 아닙니다.", trace_id)
    answers: list[dict[str, Any]] = []
    field_values: dict[str, Any] = {}
    try:
        for mapping in mappings:
            field_name = mapping["field_name"]
            raw_value = values.get(field_name)
            normalized = _normalize_answer(mapping["question"], raw_value)
            field_values[field_name] = normalized
            if normalized is not None:
                question = mapping["question"]
                answers.append(
                    {
                        "question_id": mapping["question_id"],
                        "value": normalized,
                        "evidence_turn_id": f"native-hitl-{batch['batch_id']}-{mapping['question_id']}",
                    }
                )
    except ValueError as exc:
        code = str(exc) or "ANSWER_VALUE_TYPE_INVALID"
        messages = {
            "ANSWER_REQUIRED_VALUE_MISSING": "필수 질문의 답변이 비어 있습니다. 모든 필수 입력 항목을 채운 뒤 제출해 주세요.",
            "ANSWER_CHOICE_INVALID": "선택형 질문은 안내된 선택지와 일치해야 합니다.",
            "ANSWER_VALUE_TYPE_INVALID": "답변 형식이 질문의 입력 형식과 일치하지 않습니다.",
            "ANSWER_VALUE_TOO_LARGE": "답변 길이가 허용 범위를 초과했습니다.",
        }
        return _failure(code, messages.get(code, "답변 값이 유효하지 않습니다."), trace_id)
    try:
        revision = int(batch["revision"])
        round_number = int(batch["round_number"])
    except (TypeError, ValueError):
        return _failure("CLARIFICATION_BATCH_IDENTITY_INVALID", "질문 batch revision 또는 회차가 유효하지 않습니다.", trace_id)
    now = _utc_now()
    if str(now_utc or "").strip():
        try:
            parsed = datetime.fromisoformat(str(now_utc).replace("Z", "+00:00"))
            now = parsed.replace(tzinfo=timezone.utc) if parsed.tzinfo is None else parsed.astimezone(timezone.utc)
        except ValueError:
            return _failure("SUBMITTED_AT_INVALID", "제출 시각은 ISO-8601 형식이어야 합니다.", trace_id)
    identity = {
        "batch_id": batch["batch_id"],
        "work_definition_id": batch["work_definition_id"],
        "tenant_id": batch["tenant_id"],
        "owner_id": batch["owner_id"],
        "session_id": batch["session_id"],
        "channel_mode": batch["channel_mode"],
        "revision": revision,
        "round_number": round_number,
    }
    idempotency_material = _canonical({"request_id": str(request_id or ""), **identity, "answers": answers})
    idempotency_key = "hitl-" + hashlib.sha256(idempotency_material.encode("utf-8")).hexdigest()[:32]
    submission_id = "answer-" + hashlib.sha256((idempotency_material + "|submission").encode("utf-8")).hexdigest()[:24]
    answer_submission = {
        "schema_version": "native-clarification-answer-submission/v1",
        "submission_id": submission_id,
        **identity,
        "request_id": str(request_id or ""),
        "action_id": SUBMIT_ACTION,
        "answers": answers,
        "field_values": field_values,
        "idempotency_key": idempotency_key,
        "submitted_at": _iso(now),
        "source": "langflow_native_node_input",
    }
    return {
        "ok": True,
        "status": "ANSWER_SUBMITTED",
        "route": "branch_submit_answers",
        "artifact_refs": [
            {"kind": "clarification_batch", "id": batch["batch_id"]},
            {"kind": "answer_submission", "id": submission_id},
        ],
        "clarification_batch": copy.deepcopy(batch),
        "answer_submission": answer_submission,
        "human_decision": {"action_id": SUBMIT_ACTION, "values": copy.deepcopy(values)},
        "trace_id": trace_id,
    }


class F10ClarificationAnswerGateComponent(Component):
    """Pause F10 for a 1.11.0-compatible choice, then expose one branch."""

    display_name = "42 보완 답변 안내 HITL"
    description = "질문을 확인한 뒤 답변 입력하기·추가 입력 건너뛰기·Cancel 중 하나를 선택합니다. 답변 입력하기는 1.11.0 호환 번호형 채팅 답변 안내를 반환합니다."
    icon = "MessageCircleQuestion"
    name = "F10ClarificationAnswerGate"

    inputs = [
        DataInput(
            name="clarification_batch",
            display_name="질문 Batch",
            input_types=["Data", "JSON"],
            required=True,
            info="13 재질문 Batch 생성의 재질문 Batch 출력을 연결합니다. 답변은 이후 Playground 채팅창에서 번호형으로 입력합니다.",
        ),
    ]
    outputs = [
        Output(
            name="branch_continue_chat",
            display_name="답변 입력하기",
            method="route_submission",
            types=["Data"],
            group_outputs=True,
        ),
        Output(
            name="branch_skip_additional_input",
            display_name="추가 입력 건너뛰기",
            method="route_submission",
            types=["Data"],
            group_outputs=True,
        ),
        Output(
            name="branch_cancel",
            display_name="Cancel",
            method="route_submission",
            types=["Data"],
            group_outputs=True,
        ),
        Output(
            name="blocked_path",
            display_name="입력/질문 오류",
            method="route_submission",
            types=["Data"],
            group_outputs=True,
        ),
    ]

    def _component_id(self) -> str:
        return _bounded_text(getattr(self, "_id", ""), 200) or self.name

    def _is_nonselected_group_output(self, selected: Any) -> bool:
        output_names = {"branch_continue_chat", "branch_skip_additional_input", "branch_cancel", "blocked_path"}
        current_output = str(getattr(self, "_current_output", "") or "")
        return bool(current_output and selected in output_names and current_output in output_names and current_output != selected)

    def _pause_request(self) -> dict[str, Any]:
        return build_pause_request(
            getattr(self, "clarification_batch", None),
            component_id=self._component_id(),
            run_id=getattr(getattr(self, "graph", None), "run_id", ""),
        )

    def _injected_decision(self, request_id: str) -> dict[str, Any] | None:
        graph = getattr(self, "graph", None)
        decisions = getattr(graph, "human_input_decisions", None) if graph is not None else None
        return decisions.get(request_id) if isinstance(decisions, dict) and isinstance(decisions.get(request_id), dict) else None

    def _result(self) -> dict[str, Any]:
        cached = getattr(self, "_answer_gate_result", None)
        if isinstance(cached, dict):
            # The checkpoint may restore the component instance after a pause.
            # Re-check its request id so a cached waiting envelope never hides
            # the decision injected by Langflow's resume endpoint.
            if cached.get("status") != "WAITING_ANSWER":
                return cached
            cached_request_id = ((cached.get("resume") or {}).get("request_id"))
            if self._injected_decision(str(cached_request_id or "")) is None:
                return cached
            self._answer_gate_result = None
        trace_id = f"trace-{uuid.uuid4()}"
        try:
            request = self._pause_request()
        except (TypeError, ValueError, json.JSONDecodeError) as exc:
            code = str(exc) or "CLARIFICATION_BATCH_INVALID"
            result = _failure(code, "질문 batch를 Playground HITL 안내로 변환하지 못했습니다.", trace_id)
            self._answer_gate_result = result
            return result
        decision = self._injected_decision(request["request_id"])
        if decision is None:
            graph = getattr(self, "graph", None)
            if graph is None or not callable(getattr(graph, "request_pause", None)):
                result = _failure("HITL_GRAPH_UNAVAILABLE", "Langflow graph 세션이 없어 Human Input을 일시 중지할 수 없습니다.", trace_id)
            else:
                graph.request_pause(reason=HUMAN_INPUT_REQUIRED, data=request)
                result = {
                    "ok": True,
                    "status": "WAITING_ANSWER",
                    "route": None,
                    "artifact_refs": [{"kind": "clarification_batch", "id": request["batch_id"]}],
                    "clarification_batch": _batch(getattr(self, "clarification_batch", None)),
                    "answer_submission": None,
                    "resume": {"reason": HUMAN_INPUT_REQUIRED, "request_id": request["request_id"]},
                    "trace_id": trace_id,
                }
                self.status = "Awaiting clarification answers"
            self._answer_gate_result = result
            return result
        result = build_resumed_submission(
            getattr(self, "clarification_batch", None),
            decision,
            request_id=request["request_id"],
        )
        self._answer_gate_result = result
        return result

    def build_submission(self) -> Data:
        result = self._result()
        self.status = {"ok": result.get("ok"), "status": result.get("status"), "route": result.get("route")}
        return Data(data=copy.deepcopy(result))

    def route_submission(self) -> Data:
        result = self._result()
        selected = result.get("route")
        if selected is None:
            # The first build creates the native checkpoint.  Langflow snapshots
            # every connected group output before the user resumes the run, so
            # returning the non-empty WAITING_ANSWER envelope here would make
            # both Submit and Cancel look selected to the downstream component.
            # Keep those trigger ports explicitly empty until a real decision
            # exists; build_submission above still owns the pause request.
            self.status = {"ok": result.get("ok"), "status": result.get("status"), "route": None}
            return Data(data={})
        # On the first pass the graph pauses at its checkpoint boundary.  Do
        # not stop either branch before the user actually selects an action.
        if selected in {"branch_continue_chat", "branch_skip_additional_input", "branch_cancel", "blocked_path"}:
            non_selected = [
                output_name
                for output_name in ("branch_continue_chat", "branch_skip_additional_input", "branch_cancel", "blocked_path")
                if output_name != selected
            ]
            for output_name in ("branch_continue_chat", "branch_skip_additional_input", "branch_cancel", "blocked_path"):
                if output_name != selected:
                    self.stop(output_name)
            # Built-in Human Input persists the branches it did not select
            # before a later HITL checkpoint.  This is a custom component, so
            # record the equivalent conditional exclusion ourselves whenever
            # Langflow exposes that public graph method.
            graph = getattr(self, "graph", None)
            exclude = getattr(graph, "exclude_branches_conditionally", None) if graph is not None else None
            if callable(exclude):
                exclude(self._component_id(), non_selected)
        self.status = {"ok": result.get("ok"), "status": result.get("status"), "route": selected}
        if self._is_nonselected_group_output(selected):
            return Data(data={})
        return Data(data=copy.deepcopy(result))

from __future__ import annotations

"""Commit one F10 human-answer or cancel action without sibling imports.

This compact component intentionally owns the durable answer-resume boundary:
it reads the canonical answer batch from MongoDB, validates it against the
stored WorkDefinition, applies only an allowlisted answer target, and advances
the WorkDefinition through a revision-CAS write.  It does not call another
Flow, an HTTP API, or a sibling custom component.
"""

import copy
import hashlib
import json
import math
import re
import uuid
from datetime import datetime, timezone
from typing import Any, Callable

from lfx.custom import Component
from lfx.io import DataInput, IntInput, MessageTextInput, Output, SecretStrInput
from lfx.schema import Data
from pymongo import MongoClient
from pymongo.errors import ConfigurationError, ConnectionFailure, DuplicateKeyError, PyMongoError, ServerSelectionTimeoutError


ALLOWED_CHANNELS = {"native_hitl"}
ALLOWED_ANSWER_TYPES = {"text", "single_choice", "single_choice_with_text", "multi_choice", "boolean", "number"}
FACT_STATUSES = {"confirmed", "inferred", "unknown", "conflicting"}
PRIORITY_ORDER = {"safety": 0, "branch": 1, "contract": 2, "quality": 3}
FACT_FIELDS = {"goal", "trigger", "frequency_volume", "sla", "automation_intent"}
LIST_FIELDS = {
    "scope_in",
    "scope_out",
    "actors",
    "systems",
    "inputs",
    "outputs",
    "steps",
    "exceptions",
    "pains",
    "risks_controls",
    "constraints",
    "success_criteria",
    "assumptions",
}
MAX_ID_CHARS = 200
MAX_COLLECTION_CHARS = 200
MAX_FREE_TEXT_CHARS = 16_000
MAX_ANSWER_VALUE_BYTES = 64 * 1024
MAX_WORK_DOCUMENT_BYTES = 1_000_000
MAX_RECEIPTS = 100
# F10 keeps three HITL rounds.  The final round may expose one additional
# required field so a ten-gap first extraction can still be completed without
# silently weakening the completion contract or opening a fourth pause.
MAX_QUESTIONS = 4
MAX_TARGET_PATHS_PER_QUESTION = 10
SKIP_ACTION = "skip_additional_input"
SKIP_ROUTE = "branch_skip_additional_input"
NATIVE_SKIP_SCHEMA = "native-clarification-skip-submission/v1"
WORK_SKIP_SCHEMA = "work-clarification-skip/v1"


def _payload(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        return copy.deepcopy(value)
    data = getattr(value, "data", None)
    if isinstance(data, dict):
        return copy.deepcopy(data)
    text = getattr(value, "text", value if isinstance(value, str) else "")
    if isinstance(text, str) and text.strip():
        parsed = json.loads(re.sub(r"^```(?:json)?\s*|\s*```$", "", text.strip(), flags=re.IGNORECASE))
        return copy.deepcopy(parsed) if isinstance(parsed, dict) else {}
    return {}


def _named(value: Any, *keys: str) -> dict[str, Any]:
    payload = _payload(value)
    for key in keys:
        nested = payload.get(key)
        if isinstance(nested, dict):
            return copy.deepcopy(nested)
    return payload


def _secret(value: Any) -> str:
    getter = getattr(value, "get_secret_value", None)
    return str(getter() if callable(getter) else value or "").strip()


def _utc(value: Any) -> datetime:
    text = str(value or "").strip()
    parsed = datetime.fromisoformat(text.replace("Z", "+00:00")) if text else datetime.now(timezone.utc)
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def _iso(now: datetime) -> str:
    return now.astimezone(timezone.utc).isoformat().replace("+00:00", "Z")


def _canonical(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=str)


def _failure(
    code: str,
    message: str,
    trace_id: str,
    details: dict[str, Any] | None = None,
    *,
    retryable: bool = False,
    work_definition: dict[str, Any] | None = None,
) -> dict[str, Any]:
    result: dict[str, Any] = {
        "ok": False,
        "status": "BLOCKED",
        "artifact_refs": [],
        "error": {"code": code, "message": message, "retryable": retryable, "details": details or {}},
        "resume": None,
        "trace_id": trace_id,
        "route": "blocked_path",
    }
    if isinstance(work_definition, dict):
        result["work_definition"] = _public_work(work_definition)
    return result


def _public_work(value: dict[str, Any]) -> dict[str, Any]:
    result = copy.deepcopy(value)
    result.pop("_id", None)
    result.pop("pending_action", None)
    return result


def _bounded_text(value: Any, *, max_chars: int = MAX_ID_CHARS) -> str:
    text = str(value or "").strip()
    return text if 0 < len(text) <= max_chars else ""


def _safe_collection(value: Any, default: str) -> str:
    name = str(value or default).strip()
    return name if re.fullmatch(r"[A-Za-z0-9_.-]{1,200}", name or "") else ""


def _trigger_matches(value: Any, expected_route: str) -> bool:
    """Return true only for the HITL branch this input represents.

    Langflow evaluates every connected group output when a checkpoint is
    resumed.  Component 42 therefore returns the same result envelope to its
    Submit and Cancel output methods, even though one branch is marked
    inactive.  Truthiness alone would interpret that one envelope as both
    actions.  The explicit route is the durable action discriminator.

    The small text fallback preserves direct/unit callers of the legacy public
    function, but Flow execution must use the structured route.
    """
    if value is None:
        return False
    expected_actions = {
        "branch_submit_answers": {"submit", "submit_answers", "submit answers"},
        SKIP_ROUTE: {"skip", "skip_additional_input", "skip additional input"},
        "branch_cancel": {"cancel"},
    }
    if isinstance(value, str):
        return value.strip().lower() in expected_actions.get(expected_route, set())
    try:
        payload = _payload(value)
    except (TypeError, ValueError, json.JSONDecodeError):
        return False
    route = str(payload.get("route") or "").strip()
    if route:
        return route == expected_route
    decision = payload.get("human_decision")
    if isinstance(decision, dict):
        action_id = str(decision.get("action_id") or "").strip().lower()
        return action_id in expected_actions.get(expected_route, set())
    # A direct native answer is necessarily a Submit action.  This protects
    # standalone callers that provide only the native answer contract.
    nested = payload.get("native_answer_submission") or payload.get("answer_submission")
    if expected_route == "branch_submit_answers" and isinstance(nested, dict):
        return str(nested.get("action_id") or "").strip().lower() == "submit_answers"
    skip_submission = payload.get("native_skip_submission") or payload.get("skip_submission")
    if expected_route == SKIP_ROUTE and isinstance(skip_submission, dict):
        return str(skip_submission.get("action_id") or "").strip().lower() == SKIP_ACTION
    return False


def _context(value: Any) -> tuple[dict[str, Any], dict[str, Any], int]:
    payload = _named(value, "clarification_context")
    work = payload.get("work_definition")
    completeness = payload.get("completeness")
    if not isinstance(work, dict) or not isinstance(completeness, dict):
        raise ValueError("CONTEXT_SCHEMA_INVALID")
    round_number = int(payload.get("round_number"))
    if round_number not in {1, 2, 3}:
        raise ValueError("ROUND_NUMBER_INVALID")
    return copy.deepcopy(work), copy.deepcopy(completeness), round_number


def _work_identity(work: dict[str, Any]) -> tuple[dict[str, Any], int]:
    required = ("work_definition_id", "tenant_id", "owner_id", "session_id", "channel_mode", "revision")
    missing = [name for name in required if work.get(name) in (None, "")]
    if missing:
        raise ValueError("WORK_IDENTITY_INVALID")
    identity = {name: _bounded_text(work.get(name)) for name in ("work_definition_id", "tenant_id", "owner_id", "session_id")}
    if not all(identity.values()):
        raise ValueError("WORK_IDENTITY_INVALID")
    channel = _bounded_text(work.get("channel_mode"))
    if channel not in ALLOWED_CHANNELS:
        raise ValueError("WORK_CHANNEL_INVALID")
    try:
        revision = int(work.get("revision"))
    except (TypeError, ValueError) as exc:
        raise ValueError("WORK_REVISION_INVALID") from exc
    if revision < 0:
        raise ValueError("WORK_REVISION_INVALID")
    identity["channel_mode"] = channel
    return identity, revision


def _require_same_identity(reference: dict[str, Any], current: dict[str, Any]) -> None:
    for name in ("work_definition_id", "tenant_id", "owner_id", "session_id", "channel_mode"):
        if str(reference.get(name) or "") != str(current.get(name) or ""):
            raise ValueError("WORK_CONTEXT_MISMATCH")


def _validate_context_completeness(work: dict[str, Any], completeness: dict[str, Any]) -> None:
    if str(completeness.get("work_definition_id") or "") != str(work.get("work_definition_id") or ""):
        raise ValueError("COMPLETENESS_CONTEXT_MISMATCH")
    try:
        if int(completeness.get("revision")) != int(work.get("revision")):
            raise ValueError("COMPLETENESS_CONTEXT_MISMATCH")
    except (TypeError, ValueError) as exc:
        if str(exc) == "COMPLETENESS_CONTEXT_MISMATCH":
            raise
        raise ValueError("COMPLETENESS_CONTEXT_MISMATCH") from exc


def _fact_status(value: Any) -> str:
    if isinstance(value, dict) and value.get("status") in FACT_STATUSES and "value" in value:
        return str(value.get("status"))
    if value in (None, "", [], {}):
        return "unknown"
    if isinstance(value, list):
        statuses: list[str] = []
        for item in value:
            provenance = item.get("provenance") if isinstance(item, dict) else None
            status = provenance.get("status") if isinstance(provenance, dict) else None
            if status in FACT_STATUSES:
                statuses.append(str(status))
        if "conflicting" in statuses:
            return "conflicting"
        if statuses and all(status == "confirmed" for status in statuses):
            return "confirmed"
        return "inferred"
    return "inferred"


def _plain_text(value: Any) -> str:
    if isinstance(value, dict) and "value" in value:
        value = value.get("value")
    return _canonical(value).lower() if isinstance(value, (dict, list)) else str(value or "").lower()


def _gap(code: str, path: str, priority: str, message: str, status: str = "unknown") -> dict[str, Any]:
    return {
        "reason_code": code,
        "target_paths": [path],
        "priority": priority,
        "current_status": status,
        "message": message,
    }


def evaluate_work_completeness(value: Any) -> dict[str, Any]:
    """Standalone copy of the F10 completeness contract used after merging."""
    trace_id = f"trace-{uuid.uuid4()}"
    try:
        work = _named(value, "work_definition")
        _, revision = _work_identity(work)
    except (TypeError, ValueError, json.JSONDecodeError):
        return _failure("WORK_DEFINITION_SCHEMA_INVALID", "완전성 평가에 필요한 WorkDefinition 식별자가 없습니다.", trace_id)

    gaps: list[dict[str, Any]] = []
    for field, code, message in (
        ("goal", "GOAL_UNKNOWN", "업무 목적과 완료 결과가 확인되지 않았습니다."),
        ("trigger", "TRIGGER_UNKNOWN", "업무 시작 조건 또는 주기가 확인되지 않았습니다."),
        ("inputs", "INPUT_CONTRACT_UNKNOWN", "핵심 입력과 형식이 확인되지 않았습니다."),
        ("outputs", "OUTPUT_CONTRACT_UNKNOWN", "핵심 출력과 전달 대상이 확인되지 않았습니다."),
        ("actors", "PRIMARY_ACTOR_UNKNOWN", "주요 수행자 또는 책임자가 확인되지 않았습니다."),
    ):
        status = _fact_status(work.get(field))
        if status in {"unknown", "conflicting"}:
            gaps.append(_gap(code, field, "contract", message, status))

    steps = work.get("steps") if isinstance(work.get("steps"), list) else []
    decisions = work.get("decisions") if isinstance(work.get("decisions"), list) else []
    all_text = " ".join(_plain_text(work.get(field)) for field in ("steps", "systems", "outputs", "risks_controls", "automation_intent"))
    write_or_send = bool(re.search(r"(저장|수정|삭제|발송|전송|등록|승인|write|update|delete|send|post)", all_text))
    sensitive = bool(re.search(r"(개인정보|민감|기밀|비밀번호|인증|토큰|secret|personal|restricted)", all_text))
    review_present = "human_review" in _plain_text(work.get("as_is_graph")) or bool(re.search(r"(사람|담당자|검토|승인|human.review)", _plain_text(work.get("risks_controls"))))
    if (write_or_send or sensitive) and not review_present:
        gaps.append(
            _gap(
                "WRITE_APPROVAL_UNKNOWN" if write_or_send else "SENSITIVE_REVIEW_UNKNOWN",
                "risks_controls",
                "safety",
                "외부 변경·발송 또는 민감정보 처리 전에 필요한 권한과 사람 검토 위치가 확인되지 않았습니다.",
            )
        )
    if not steps:
        gaps.append(_gap("STEP_SEQUENCE_UNKNOWN", "steps", "branch", "업무 단계의 순서가 확인되지 않았습니다."))
    for index, decision in enumerate(decisions):
        if not isinstance(decision, dict):
            gaps.append(_gap("DECISION_SCHEMA_INVALID", "decisions", "branch", "분기 정보 형식이 올바르지 않습니다.", "conflicting"))
            continue
        branches = decision.get("branches") or decision.get("outcomes")
        if not decision.get("condition") or not isinstance(branches, list) or len(branches) < 2:
            gaps.append(_gap("BRANCH_CONDITION_UNKNOWN", f"decisions[{index}]", "branch", "판단 조건과 두 개 이상의 분기 결과가 확인되지 않았습니다."))
    for field, code, message in (
        ("exceptions", "FAILURE_POLICY_UNKNOWN", "실패·예외 발생 시 처리 방식이 확인되지 않았습니다."),
        ("sla", "SLA_UNKNOWN", "기한 또는 허용 처리 시간이 확인되지 않았습니다."),
        ("success_criteria", "SUCCESS_CRITERIA_UNKNOWN", "완료 품질을 판단할 측정 기준이 확인되지 않았습니다."),
    ):
        status = _fact_status(work.get(field))
        if status in {"unknown", "conflicting"}:
            gaps.append(_gap(code, field, "quality", message, status))
    scope_in = {_plain_text(item) for item in (work.get("scope_in") or [])}
    scope_out = {_plain_text(item) for item in (work.get("scope_out") or [])}
    overlap = sorted(item for item in scope_in & scope_out if item)
    if overlap:
        gaps.append({**_gap("SCOPE_CONFLICT", "scope_in", "branch", "포함 범위와 제외 범위가 충돌합니다.", "conflicting"), "conflicting_values": overlap[:20]})
    gaps.sort(key=lambda item: (PRIORITY_ORDER.get(str(item.get("priority")), 99), str(item.get("reason_code")), str((item.get("target_paths") or [""])[0])))
    evaluation = {
        "work_definition_id": work["work_definition_id"],
        "tenant_id": work["tenant_id"],
        "session_id": work["session_id"],
        "revision": revision,
        "channel_mode": work.get("channel_mode"),
        "needs_clarification": bool(gaps),
        "blocking_gap_count": len(gaps),
        "blocking_gaps": gaps,
        "question_policy": {"max_questions_per_round": 3, "priority_order": ["safety", "branch", "contract", "quality"]},
    }
    return {
        "ok": True,
        "status": "NEEDS_CLARIFICATION" if gaps else "READY_FOR_REVIEW",
        "artifact_refs": [{"kind": "work_definition", "id": work["work_definition_id"], "revision": revision}],
        "completeness": evaluation,
        "trace_id": trace_id,
    }


def _normalize_answer_value(question: dict[str, Any], value: Any) -> Any:
    answer_type = str(question.get("answer_type") or "text")
    if answer_type not in ALLOWED_ANSWER_TYPES:
        raise ValueError("ANSWER_VALUE_TYPE_INVALID")
    raw_choices = question.get("choices") if isinstance(question.get("choices"), list) else []
    choices = [str(item) for item in raw_choices if isinstance(item, str)][:20]
    required = bool(question.get("required", True))
    if value in (None, "", []):
        if required:
            raise ValueError("ANSWER_REQUIRED_VALUE_MISSING")
        return None
    if answer_type == "text":
        if not isinstance(value, str) or len(value) > MAX_FREE_TEXT_CHARS:
            raise ValueError("ANSWER_VALUE_TYPE_INVALID")
        normalized: Any = value
    elif answer_type == "single_choice":
        if not isinstance(value, str) or value not in choices:
            raise ValueError("ANSWER_CHOICE_INVALID")
        normalized = value
    elif answer_type == "single_choice_with_text":
        if isinstance(value, str) and value in choices:
            normalized = {"choice": value, "text": ""}
        elif isinstance(value, dict) and set(value) <= {"choice", "text"}:
            choice = value.get("choice")
            text = value.get("text", "")
            if not isinstance(choice, str) or not isinstance(text, str) or len(text) > MAX_FREE_TEXT_CHARS:
                raise ValueError("ANSWER_VALUE_TYPE_INVALID")
            if choice == "__other__":
                if not text.strip():
                    raise ValueError("ANSWER_REQUIRED_VALUE_MISSING")
            elif choice not in choices:
                raise ValueError("ANSWER_CHOICE_INVALID")
            normalized = {"choice": choice, "text": text}
        else:
            raise ValueError("ANSWER_VALUE_TYPE_INVALID")
    elif answer_type == "multi_choice":
        if not isinstance(value, list) or not value or any(not isinstance(item, str) or item not in choices for item in value):
            raise ValueError("ANSWER_CHOICE_INVALID")
        normalized = list(dict.fromkeys(value))
    elif answer_type == "boolean":
        if not isinstance(value, bool):
            raise ValueError("ANSWER_VALUE_TYPE_INVALID")
        normalized = value
    else:
        if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(float(value)) or abs(float(value)) > 1e15:
            raise ValueError("ANSWER_VALUE_TYPE_INVALID")
        normalized = value
    if len(_canonical(normalized).encode("utf-8")) > MAX_ANSWER_VALUE_BYTES:
        raise ValueError("ANSWER_VALUE_TOO_LARGE")
    return normalized


def _path_tokens(path: Any) -> list[str | int]:
    text = str(path or "")
    if not text or len(text) > 300 or not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*(?:\[\d+\])?", text):
        return []
    tokens: list[str | int] = []
    for key, index in re.findall(r"([A-Za-z_][A-Za-z0-9_]*)|\[(\d+)\]", text):
        tokens.append(int(index) if index else key)
    if len(tokens) > 2 or any(isinstance(token, int) and token >= 500 for token in tokens):
        return []
    return tokens


def _allowed_path(tokens: list[str | int]) -> bool:
    if len(tokens) == 1 and isinstance(tokens[0], str) and tokens[0] in FACT_FIELDS | LIST_FIELDS:
        return True
    return len(tokens) == 2 and tokens[0] == "decisions" and isinstance(tokens[1], int)


def _get_path(root: Any, tokens: list[str | int]) -> Any:
    current = root
    for token in tokens:
        if isinstance(token, str) and isinstance(current, dict):
            current = current.get(token)
        elif isinstance(token, int) and isinstance(current, list) and 0 <= token < len(current):
            current = current[token]
        else:
            return None
    return current


def _set_path(root: dict[str, Any], tokens: list[str | int], value: Any) -> bool:
    if not _allowed_path(tokens) or not isinstance(tokens[0], str):
        return False
    if len(tokens) == 1:
        root[tokens[0]] = value
        return True
    decisions = root.get("decisions")
    if not isinstance(decisions, list) or not isinstance(tokens[1], int) or tokens[1] < 0 or tokens[1] >= len(decisions):
        return False
    decisions[tokens[1]] = value
    return True


def _same(left: Any, right: Any) -> bool:
    return _canonical(left) == _canonical(right)


def _evidence(existing: Any, turn_id: str) -> list[str]:
    result: list[str] = []
    current = existing if isinstance(existing, list) else []
    for item in current + [turn_id]:
        text = _bounded_text(item)
        if text and text not in result:
            result.append(text)
    return result[:MAX_RECEIPTS]


def _merge_fact(current: Any, incoming: Any, *, revision: int, evidence_turn_id: str, resolve_conflict: bool) -> tuple[dict[str, Any], bool]:
    fact = copy.deepcopy(current) if isinstance(current, dict) and current.get("status") in FACT_STATUSES and "value" in current else {
        "value": copy.deepcopy(current) if current not in (None, "") else None,
        "status": "unknown" if current in (None, "") else "inferred",
        "evidence_turn_ids": [],
        "confidence": 0.0 if current in (None, "") else 0.7,
        "last_updated_revision": max(0, revision - 1),
    }
    old_value = copy.deepcopy(fact.get("value"))
    evidence = _evidence(fact.get("evidence_turn_ids"), evidence_turn_id)
    if fact.get("status") in {"confirmed", "conflicting"} and not _same(old_value, incoming) and not resolve_conflict:
        candidates = copy.deepcopy(fact.get("conflicting_values")) if isinstance(fact.get("conflicting_values"), list) else []
        for candidate in (old_value, copy.deepcopy(incoming)):
            if not any(_same(candidate, known) for known in candidates):
                candidates.append(candidate)
        return {
            "value": old_value,
            "status": "conflicting",
            "conflicting_values": candidates[:20],
            "evidence_turn_ids": evidence,
            "confidence": 0.0,
            "last_updated_revision": revision,
        }, True
    return {
        "value": copy.deepcopy(incoming),
        "status": "confirmed",
        "evidence_turn_ids": evidence,
        "confidence": 1.0,
        "last_updated_revision": revision,
    }, False


def _confirmed_list(value: Any, *, path: str, revision: int, evidence_turn_id: str) -> list[dict[str, Any]]:
    raw_items = value if isinstance(value, list) else [value]
    result: list[dict[str, Any]] = []
    for index, item in enumerate(raw_items[:500]):
        record = copy.deepcopy(item) if isinstance(item, dict) else {"value": copy.deepcopy(item)}
        identity = record.get("id") or record.get("name") or record.get("label") or record.get("title") or record.get("value") or index
        material = f"{path}|{identity}"
        record.setdefault("id", f"{path.rstrip('s') or 'item'}-{hashlib.sha256(material.encode('utf-8')).hexdigest()[:16]}")
        existing = record.get("provenance") if isinstance(record.get("provenance"), dict) else {}
        record["provenance"] = {
            "status": "confirmed",
            "evidence_turn_ids": _evidence(existing.get("evidence_turn_ids"), evidence_turn_id),
            "confidence": 1.0,
            "last_updated_revision": revision,
        }
        result.append(record)
    return result


def _merge_decision(current: Any, incoming: Any, *, revision: int, evidence_turn_id: str, resolve_conflict: bool) -> tuple[dict[str, Any], bool]:
    if isinstance(incoming, str):
        if len(incoming) > MAX_FREE_TEXT_CHARS:
            raise ValueError("ANSWER_DECISION_INVALID")
        try:
            incoming = json.loads(incoming)
        except json.JSONDecodeError as exc:
            raise ValueError("ANSWER_DECISION_INVALID") from exc
    if not isinstance(incoming, dict):
        raise ValueError("ANSWER_DECISION_INVALID")
    condition = _bounded_text(incoming.get("condition"), max_chars=2_000)
    branches = incoming.get("branches") if isinstance(incoming.get("branches"), list) else incoming.get("outcomes")
    if not condition or not isinstance(branches, list) or not 2 <= len(branches) <= 20:
        raise ValueError("ANSWER_DECISION_INVALID")
    normalized: list[dict[str, Any]] = []
    for index, branch in enumerate(branches):
        record = copy.deepcopy(branch) if isinstance(branch, dict) else {"label": str(branch)}
        label = _bounded_text(record.get("label") or record.get("name") or record.get("value"), max_chars=500)
        if not label:
            raise ValueError("ANSWER_DECISION_INVALID")
        record["label"] = label
        record.setdefault("branch_id", f"branch-{index + 1}")
        normalized.append(record)
    base = copy.deepcopy(current) if isinstance(current, dict) else {}
    previous = {"condition": base.get("condition"), "branches": base.get("branches") or base.get("outcomes")}
    candidate = {"condition": condition, "branches": normalized}
    provenance = base.get("provenance") if isinstance(base.get("provenance"), dict) else {}
    if provenance.get("status") == "confirmed" and not _same(previous, candidate) and not resolve_conflict:
        base["provenance"] = {
            "status": "conflicting",
            "evidence_turn_ids": _evidence(provenance.get("evidence_turn_ids"), evidence_turn_id),
            "confidence": 0.0,
            "last_updated_revision": revision,
        }
        return base, True
    base.pop("outcomes", None)
    base["condition"] = condition
    base["branches"] = normalized
    base["provenance"] = {
        "status": "confirmed",
        "evidence_turn_ids": _evidence(provenance.get("evidence_turn_ids"), evidence_turn_id),
        "confidence": 1.0,
        "last_updated_revision": revision,
    }
    return base, False


def _batch_reference(value: Any) -> dict[str, Any]:
    batch = _named(value, "clarification_batch")
    batch_id = _bounded_text(batch.get("batch_id"), max_chars=MAX_ID_CHARS)
    if not batch_id:
        raise ValueError("CLARIFICATION_BATCH_REFERENCE_INVALID")
    return batch


def _canonical_answered_batch(value: dict[str, Any]) -> dict[str, Any]:
    """Normalize the trusted HITL service's resume records to one answer view.

    The Answer Form service persists a submission as
    ``ANSWERED_PENDING_RESUME`` and may subsequently mark it ``RESUMED``.  A
    compact Langflow resume reads that MongoDB record directly, so it must use
    the nested immutable submission rather than expect a synthetic flat
    ``ANSWERED`` record.  The original batch identity remains authoritative;
    every identity carried by the nested submission is checked before copying
    answer fields out of it.
    """
    batch = copy.deepcopy(value)
    status = str(batch.get("status") or "")
    if status not in {"ANSWERED_PENDING_RESUME", "RESUMED"}:
        return batch
    submission = batch.get("answer_submission")
    if isinstance(submission, dict):
        for name in ("work_definition_id", "tenant_id", "batch_id", "channel_mode"):
            if str(submission.get(name) or "") != str(batch.get(name) or ""):
                raise ValueError("ANSWER_SUBMISSION_IDENTITY_MISMATCH")
        submitted_session = submission.get("session_id")
        if submitted_session not in (None, "") and str(submitted_session) != str(batch.get("session_id") or ""):
            raise ValueError("ANSWER_SUBMISSION_IDENTITY_MISMATCH")
        submitted_actor = submission.get("actor_id")
        if submitted_actor not in (None, "") and str(submitted_actor) != str(batch.get("owner_id") or ""):
            raise ValueError("ANSWER_SUBMISSION_ACTOR_MISMATCH")
        try:
            if int(submission.get("expected_revision")) != int(batch.get("revision")):
                raise ValueError("REVISION_CONFLICT")
        except (TypeError, ValueError) as exc:
            if str(exc) == "REVISION_CONFLICT":
                raise
            raise ValueError("ANSWER_SUBMISSION_REVISION_INVALID") from exc
        batch["answers"] = copy.deepcopy(submission.get("answers"))
        batch["answer_idempotency_key"] = submission.get("idempotency_key")
        batch["answered_at"] = submission.get("submitted_at")
        batch["answer_turn_id"] = submission.get("turn_id") or batch.get("answer_turn_id")
    elif batch.get("answers") is None:
        return batch
    batch["status"] = "ANSWERED"
    batch.pop("answer_submission", None)
    return batch


def _validate_batch(
    batch: dict[str, Any],
    batch_reference: dict[str, Any],
    durable_work: dict[str, Any],
    *,
    round_number: int,
    now: datetime,
) -> tuple[list[dict[str, Any]], str, str]:
    batch = _canonical_answered_batch(batch)
    _require_same_identity(batch, durable_work)
    for name in ("batch_id", "work_definition_id", "tenant_id", "owner_id", "session_id", "channel_mode", "revision", "round_number"):
        incoming = batch_reference.get(name)
        if incoming not in (None, "") and str(incoming) != str(batch.get(name)):
            raise ValueError("CLARIFICATION_BATCH_REFERENCE_MISMATCH")
    if str(batch.get("status") or "") != "ANSWERED":
        raise ValueError("ANSWER_FORM_NOT_SUBMITTED")
    try:
        if int(batch.get("revision")) != int(durable_work.get("revision")):
            raise ValueError("REVISION_CONFLICT")
        if int(batch.get("round_number")) != round_number:
            raise ValueError("CLARIFICATION_ROUND_MISMATCH")
    except (TypeError, ValueError) as exc:
        if str(exc) in {"REVISION_CONFLICT", "CLARIFICATION_ROUND_MISMATCH"}:
            raise
        raise ValueError("ANSWER_BATCH_REVISION_INVALID") from exc
    try:
        submitted_at = _utc(batch.get("answered_at"))
        expires_at = _utc(batch.get("answer_deadline_at") or batch.get("expires_at"))
    except (TypeError, ValueError) as exc:
        raise ValueError("ANSWER_BATCH_EXPIRY_INVALID") from exc
    if submitted_at >= expires_at:
        raise ValueError("ANSWER_BATCH_EXPIRED")
    idempotency_key = _bounded_text(batch.get("answer_idempotency_key"), max_chars=300)
    if not idempotency_key:
        raise ValueError("ANSWER_IDEMPOTENCY_KEY_REQUIRED")
    questions = [copy.deepcopy(item) for item in batch.get("questions", []) if isinstance(item, dict) and _bounded_text(item.get("question_id"))]
    if not 1 <= len(questions) <= MAX_QUESTIONS:
        raise ValueError("CLARIFICATION_QUESTION_CONTRACT_INVALID")
    question_ids = [str(item["question_id"]) for item in questions]
    if len(question_ids) != len(set(question_ids)):
        raise ValueError("CLARIFICATION_QUESTION_CONTRACT_INVALID")
    raw_answers = batch.get("answers")
    if isinstance(raw_answers, dict):
        raw_answers = [{"question_id": key, "value": value} for key, value in raw_answers.items()]
    if not isinstance(raw_answers, list) or not raw_answers:
        raise ValueError("ANSWER_LIST_INVALID")
    question_by_id = {str(item["question_id"]): item for item in questions}
    normalized: list[dict[str, Any]] = []
    seen: set[str] = set()
    for item in raw_answers[:MAX_QUESTIONS]:
        if not isinstance(item, dict):
            raise ValueError("ANSWER_ITEM_INVALID")
        question_id = _bounded_text(item.get("question_id"))
        if question_id not in question_by_id or question_id in seen:
            raise ValueError("ANSWER_QUESTION_INVALID")
        question = question_by_id[question_id]
        paths = question.get("target_paths") if isinstance(question.get("target_paths"), list) else []
        safe_paths: list[str] = []
        for raw_path in paths[:MAX_TARGET_PATHS_PER_QUESTION]:
            tokens = _path_tokens(raw_path)
            if not tokens or not _allowed_path(tokens):
                raise ValueError("ANSWER_TARGET_PATH_FORBIDDEN")
            path = str(raw_path)
            if path not in safe_paths:
                safe_paths.append(path)
        if not safe_paths:
            raise ValueError("ANSWER_TARGET_PATH_MISSING")
        try:
            answer_value = _normalize_answer_value(question, copy.deepcopy(item.get("value")))
        except ValueError:
            raise
        normalized.append(
            {
                "question_id": question_id,
                "value": answer_value,
                "target_paths": safe_paths,
                "reason_code": _bounded_text(question.get("reason_code"), max_chars=100),
                "resolve_conflict": bool(item.get("resolve_conflict", False)),
                "evidence_turn_id": _bounded_text(item.get("evidence_turn_id") or batch.get("answer_turn_id") or f"answer-{question_id}"),
            }
        )
        seen.add(question_id)
    if len(raw_answers) > MAX_QUESTIONS:
        raise ValueError("ANSWER_LIST_INVALID")
    missing_required = [question_id for question_id, question in question_by_id.items() if bool(question.get("required", True)) and question_id not in seen]
    if missing_required:
        raise ValueError("ANSWER_REQUIRED_QUESTIONS_MISSING")
    material = _canonical({"batch_id": batch.get("batch_id"), "idempotency_key": idempotency_key, "answers": normalized})
    return normalized, idempotency_key, hashlib.sha256(material.encode("utf-8")).hexdigest()


def _apply_answers(work: dict[str, Any], answers: list[dict[str, Any]], *, batch_id: str, idempotency_key: str, payload_hash: str) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    updated = copy.deepcopy(work)
    current_revision = int(updated.get("revision"))
    new_revision = current_revision + 1
    conflicts: list[dict[str, Any]] = []
    changed_paths: list[str] = []
    for answer in answers:
        for path in answer["target_paths"]:
            tokens = _path_tokens(path)
            if not _allowed_path(tokens):
                raise ValueError("ANSWER_TARGET_PATH_FORBIDDEN")
            current = _get_path(updated, tokens)
            if len(tokens) == 1 and str(tokens[0]) in LIST_FIELDS:
                incoming = _confirmed_list(answer["value"], path=path, revision=new_revision, evidence_turn_id=answer["evidence_turn_id"])
                confirmed = isinstance(current, list) and current and all(isinstance(item, dict) and ((item.get("provenance") or {}).get("status") == "confirmed") for item in current)
                if confirmed and not _same(current, incoming) and not answer["resolve_conflict"]:
                    conflicts.append({"path": path, "question_id": answer["question_id"], "reason": "CONFIRMED_VALUE_CHANGED"})
                    continue
                merged, conflict = incoming, False
            elif len(tokens) == 2 and tokens[0] == "decisions":
                merged, conflict = _merge_decision(current, answer["value"], revision=new_revision, evidence_turn_id=answer["evidence_turn_id"], resolve_conflict=answer["resolve_conflict"])
            else:
                merged, conflict = _merge_fact(current, answer["value"], revision=new_revision, evidence_turn_id=answer["evidence_turn_id"], resolve_conflict=answer["resolve_conflict"])
            if not _set_path(updated, tokens, merged):
                raise ValueError("ANSWER_TARGET_PATH_INVALID")
            changed_paths.append(path)
            if conflict:
                conflicts.append({"path": path, "question_id": answer["question_id"], "reason": "CONFIRMED_VALUE_CHANGED"})
    updated["revision"] = new_revision
    updated["approved_hash"] = None
    receipts = copy.deepcopy(updated.get("processed_answer_batches")) if isinstance(updated.get("processed_answer_batches"), list) else []
    receipts.append(
        {
            "batch_id": batch_id,
            "idempotency_key": idempotency_key,
            "payload_sha256": payload_hash,
            "resulting_revision": new_revision,
            "changed_paths": sorted(set(changed_paths)),
            "conflicts": copy.deepcopy(conflicts),
        }
    )
    updated["processed_answer_batches"] = receipts[-MAX_RECEIPTS:]
    return updated, conflicts


def _check_bounded_document(document: dict[str, Any]) -> None:
    if len(_canonical(document).encode("utf-8")) > MAX_WORK_DOCUMENT_BYTES:
        raise ValueError("WORK_DOCUMENT_TOO_LARGE")


def _initial_work_document(context_work: dict[str, Any], identity: dict[str, str], *, now: datetime) -> dict[str, Any]:
    """Create the first canonical record only from the validated F10 context."""
    _, revision = _work_identity(context_work)
    if revision != 0:
        raise ValueError("WORK_DEFINITION_NOT_FOUND")
    document = copy.deepcopy(context_work)
    document["_id"] = "work-definition:" + hashlib.sha256(
        f"{identity['tenant_id']}|{identity['work_definition_id']}".encode("utf-8")
    ).hexdigest()
    document["revision"] = 0
    document["status"] = "WAITING_ANSWER"
    document["approved_hash"] = None
    document["created_at"] = now
    document["updated_at"] = now
    document["processed_answer_batches"] = []
    document["f10_action_receipts"] = []
    _check_bounded_document(document)
    return document


def _load_or_create_initial_work(
    definitions: Any,
    identity: dict[str, str],
    context_work: dict[str, Any],
    *,
    now: datetime,
) -> tuple[dict[str, Any], bool]:
    query = {"tenant_id": identity["tenant_id"], "work_definition_id": identity["work_definition_id"]}
    existing = definitions.find_one(query)
    if isinstance(existing, dict):
        return existing, False
    initial = _initial_work_document(context_work, identity, now=now)
    try:
        definitions.insert_one(initial)
        return initial, True
    except DuplicateKeyError:
        existing = definitions.find_one(query)
        if isinstance(existing, dict):
            return existing, False
        raise


def _action_receipt(document: dict[str, Any], *, action: str, now: datetime, actor_id: str) -> None:
    receipts = copy.deepcopy(document.get("f10_action_receipts")) if isinstance(document.get("f10_action_receipts"), list) else []
    receipts.append({"action": action, "actor_id": actor_id, "recorded_at": now})
    document["f10_action_receipts"] = receipts[-MAX_RECEIPTS:]


def _route_result(
    work: dict[str, Any],
    evaluation: dict[str, Any],
    *,
    route: str,
    round_number: int,
    trace_id: str,
    error: dict[str, Any] | None = None,
) -> dict[str, Any]:
    public = _public_work(work)
    result: dict[str, Any] = {
        "ok": True,
        "status": str(public.get("status") or ""),
        "artifact_refs": [{"kind": "work_definition", "id": public.get("work_definition_id"), "revision": public.get("revision")}],
        "work_definition": public,
        "completeness": copy.deepcopy(evaluation),
        "round_number": round_number,
        "route": route,
        "trace_id": trace_id,
    }
    if route == "next_round_path":
        result["next_round_number"] = round_number + 1
    if error is not None:
        result["error"] = error
    return result


def _commit_cancel(
    definitions: Any,
    identity: dict[str, str],
    context_work: dict[str, Any],
    *,
    actor_id: str,
    now: datetime,
    trace_id: str,
) -> dict[str, Any]:
    durable: dict[str, Any] | None = None
    if actor_id != identity["owner_id"]:
        return _failure("ACTION_ACTOR_MISMATCH", "업무 owner만 질문 세션을 취소할 수 있습니다.", trace_id, work_definition=context_work)
    try:
        durable, _ = _load_or_create_initial_work(definitions, identity, context_work, now=now)
        _require_same_identity(context_work, durable)
        _, expected_revision = _work_identity(durable)
        if expected_revision != int(context_work.get("revision")):
            raise ValueError("REVISION_CONFLICT")
    except ValueError as exc:
        return _failure(str(exc), "취소 대상 WorkDefinition의 식별자 또는 channel이 일치하지 않습니다.", trace_id, work_definition=durable)
    if actor_id != str(durable.get("owner_id")):
        return _failure("ACTION_ACTOR_MISMATCH", "업무 owner만 질문 세션을 취소할 수 있습니다.", trace_id, work_definition=durable)
    if str(durable.get("status")) == "CANCELLED":
        return {
            "ok": True,
            "status": "CANCELLED",
            "artifact_refs": [{"kind": "work_definition", "id": durable["work_definition_id"], "revision": durable["revision"]}],
            "work_definition": _public_work(durable),
            "route": "cancelled_path",
            "trace_id": trace_id,
            "store_result": {"idempotent_replay": True, "revision": durable["revision"]},
        }
    cancelled = copy.deepcopy(durable)
    cancelled["revision"] = expected_revision + 1
    cancelled["status"] = "CANCELLED"
    cancelled["approved_hash"] = None
    cancelled["updated_at"] = now
    cancelled["cancelled_at"] = now
    _action_receipt(cancelled, action="cancel", now=now, actor_id=actor_id)
    try:
        _check_bounded_document(cancelled)
    except ValueError:
        return _failure("WORK_DOCUMENT_TOO_LARGE", "취소 결과 WorkDefinition이 허용 크기를 초과합니다.", trace_id, work_definition=durable)
    write = definitions.replace_one(
        {"tenant_id": identity["tenant_id"], "work_definition_id": identity["work_definition_id"], "revision": expected_revision},
        cancelled,
    )
    if int(getattr(write, "matched_count", 0)) != 1:
        return _failure("REVISION_CONFLICT", "취소 중 WorkDefinition revision 충돌이 발생했습니다.", trace_id, retryable=True, work_definition=durable)
    return {
        "ok": True,
        "status": "CANCELLED",
        "artifact_refs": [{"kind": "work_definition", "id": cancelled["work_definition_id"], "revision": cancelled["revision"]}],
        "work_definition": _public_work(cancelled),
        "route": "cancelled_path",
        "trace_id": trace_id,
        "store_result": {"idempotent_replay": False, "revision": cancelled["revision"]},
    }


def _native_submission(value: Any) -> dict[str, Any] | None:
    """Read the direct Playground answer emitted by Component 42.

    A native Human Input resume returns the selected action plus ``values`` to
    the custom gate.  The gate turns it into a bounded answer contract so this
    component can keep MongoDB as the canonical audit source without requiring
    a separate Answer Form service.
    """

    payload = _payload(value)
    nested = payload.get("native_answer_submission") or payload.get("answer_submission")
    candidate = nested if isinstance(nested, dict) else payload
    if not isinstance(candidate, dict):
        return None
    if str(candidate.get("schema_version") or "") != "native-clarification-answer-submission/v1":
        return None
    return copy.deepcopy(candidate)


def _native_skip_submission(value: Any) -> dict[str, Any] | None:
    """Read Component 42's explicit native HITL skip event.

    A skip is deliberately not treated as an empty answer submission.  It has
    its own action and schema so a user cannot accidentally submit partial
    values while asking to continue without more input.
    """

    payload = _payload(value)
    nested = payload.get("native_skip_submission") or payload.get("skip_submission")
    candidate = nested if isinstance(nested, dict) else payload
    if not isinstance(candidate, dict):
        return None
    if str(candidate.get("schema_version") or "") != NATIVE_SKIP_SCHEMA:
        return None
    return copy.deepcopy(candidate)


def _canonical_native_skip_submission(
    batch: dict[str, Any],
    native: dict[str, Any],
    *,
    actor_id: str,
    round_number: int,
    now: datetime,
) -> tuple[dict[str, Any], str]:
    """Validate a native skip action and make it a durable audit record."""

    if str(native.get("action_id") or "") != SKIP_ACTION:
        raise ValueError("NATIVE_SKIP_ACTION_INVALID")
    for name in (
        "batch_id",
        "work_definition_id",
        "tenant_id",
        "owner_id",
        "session_id",
        "channel_mode",
        "revision",
        "round_number",
    ):
        if name not in native or str(native.get(name)) != str(batch.get(name)):
            raise ValueError("NATIVE_SKIP_CONTEXT_MISMATCH")
    try:
        if int(native.get("round_number", -1)) != int(round_number):
            raise ValueError("CLARIFICATION_ROUND_MISMATCH")
    except (TypeError, ValueError) as exc:
        if str(exc) == "CLARIFICATION_ROUND_MISMATCH":
            raise
        raise ValueError("NATIVE_SKIP_CONTEXT_MISMATCH") from exc
    if str(native.get("owner_id") or "") != actor_id:
        raise ValueError("ACTION_ACTOR_MISMATCH")

    request_id = _bounded_text(native.get("request_id"), max_chars=MAX_ID_CHARS)
    questions = batch.get("questions") if isinstance(batch.get("questions"), list) else []
    question_ids = [_bounded_text(item.get("question_id"), max_chars=MAX_ID_CHARS) for item in questions if isinstance(item, dict)]
    if not request_id or not 1 <= len(question_ids) <= MAX_QUESTIONS or not all(question_ids) or len(question_ids) != len(set(question_ids)):
        raise ValueError("NATIVE_SKIP_SUBMISSION_INVALID")
    raw_skipped = native.get("skipped_question_ids")
    if not isinstance(raw_skipped, list):
        raise ValueError("NATIVE_SKIP_SUBMISSION_INVALID")
    skipped_question_ids = [_bounded_text(item, max_chars=MAX_ID_CHARS) for item in raw_skipped]
    # A skip applies to the entire displayed card.  Requiring this exact,
    # ordered list prevents a crafted event from hiding only selected fields.
    if skipped_question_ids != question_ids:
        raise ValueError("NATIVE_SKIP_SUBMISSION_INVALID")

    material = _canonical(
        {
            "batch_id": batch.get("batch_id"),
            "request_id": request_id,
            "action_id": SKIP_ACTION,
            "skipped_question_ids": skipped_question_ids,
        }
    )
    request_hash = hashlib.sha256(material.encode("utf-8")).hexdigest()
    idempotency_key = "native-hitl-skip-" + request_hash
    skip_id = "skip-" + hashlib.sha256(f"{batch.get('batch_id')}|{idempotency_key}|{request_hash}".encode("utf-8")).hexdigest()[:24]
    submission = {
        "schema_version": WORK_SKIP_SCHEMA,
        "skip_id": skip_id,
        "idempotency_key": idempotency_key,
        "channel_mode": batch.get("channel_mode"),
        "work_definition_id": batch.get("work_definition_id"),
        "tenant_id": batch.get("tenant_id"),
        "session_id": batch.get("session_id"),
        "batch_id": batch.get("batch_id"),
        "expected_revision": int(batch.get("revision")),
        "round_number": int(batch.get("round_number")),
        "skipped_question_ids": skipped_question_ids,
        "skipped_at": now,
        "actor_id": actor_id,
        "request_id": request_id,
        "action_id": SKIP_ACTION,
    }
    return submission, request_hash


def _native_pending_skip_batch(
    batch: dict[str, Any],
    native: dict[str, Any],
    *,
    actor_id: str,
    round_number: int,
    now: datetime,
) -> tuple[dict[str, Any], dict[str, Any], str]:
    """Create, but do not persist, an immutable explicit-skip batch record."""

    submission, request_hash = _canonical_native_skip_submission(
        batch,
        native,
        actor_id=actor_id,
        round_number=round_number,
        now=now,
    )
    candidate = copy.deepcopy(batch)
    candidate["status"] = "SKIPPED_PENDING_REVIEW"
    candidate["skip_submission"] = copy.deepcopy(submission)
    candidate["skip_idempotency_key"] = str(submission["idempotency_key"])
    candidate["skip_request_hash"] = request_hash
    return candidate, submission, request_hash


def _persist_native_skip(
    batches: Any,
    batch: dict[str, Any],
    native: dict[str, Any],
    *,
    actor_id: str,
    round_number: int,
    now: datetime,
) -> tuple[dict[str, Any], str]:
    """CAS-persist one explicit skip so it is auditable and idempotent."""

    candidate, submission, request_hash = _native_pending_skip_batch(
        batch,
        native,
        actor_id=actor_id,
        round_number=round_number,
        now=now,
    )
    idempotency_key = str(submission["idempotency_key"])
    identity = {
        "tenant_id": batch.get("tenant_id"),
        "work_definition_id": batch.get("work_definition_id"),
        "batch_id": batch.get("batch_id"),
        "status": "WAITING_ANSWER",
    }
    write = batches.replace_one(identity, candidate)
    if int(getattr(write, "matched_count", 0)) == 1:
        return candidate, str(submission["skip_id"])
    current = batches.find_one(
        {
            "tenant_id": batch.get("tenant_id"),
            "work_definition_id": batch.get("work_definition_id"),
            "batch_id": batch.get("batch_id"),
        }
    )
    if not isinstance(current, dict):
        raise ValueError("ANSWER_BATCH_NOT_FOUND")
    current_submission = current.get("skip_submission") if isinstance(current.get("skip_submission"), dict) else {}
    if (
        str(current.get("status") or "") in {"SKIPPED_PENDING_REVIEW", "RESUMED"}
        and str(current_submission.get("idempotency_key") or "") == idempotency_key
        and str(current.get("skip_request_hash") or "") == request_hash
    ):
        return current, str(current_submission.get("skip_id") or submission["skip_id"])
    raise ValueError("NATIVE_SKIP_ALREADY_SUBMITTED")


def _validate_skip_batch(
    batch: dict[str, Any],
    batch_reference: dict[str, Any],
    durable_work: dict[str, Any],
    *,
    round_number: int,
    now: datetime,
) -> None:
    """Validate a still-waiting batch before recording a user-approved skip."""

    _require_same_identity(batch, durable_work)
    for name in ("batch_id", "work_definition_id", "tenant_id", "owner_id", "session_id", "channel_mode", "revision", "round_number"):
        incoming = batch_reference.get(name)
        if incoming not in (None, "") and str(incoming) != str(batch.get(name)):
            raise ValueError("CLARIFICATION_BATCH_REFERENCE_MISMATCH")
    if str(batch.get("status") or "") not in {"WAITING_ANSWER", "SKIPPED_PENDING_REVIEW", "RESUMED"}:
        raise ValueError("ANSWER_FORM_NOT_SUBMITTED")
    try:
        if int(batch.get("revision")) != int(durable_work.get("revision")):
            raise ValueError("REVISION_CONFLICT")
        if int(batch.get("round_number")) != round_number:
            raise ValueError("CLARIFICATION_ROUND_MISMATCH")
        expires_at = _utc(batch.get("answer_deadline_at") or batch.get("expires_at"))
    except (TypeError, ValueError) as exc:
        if str(exc) in {"REVISION_CONFLICT", "CLARIFICATION_ROUND_MISMATCH"}:
            raise
        raise ValueError("ANSWER_BATCH_EXPIRY_INVALID") from exc
    if now >= expires_at:
        raise ValueError("ANSWER_BATCH_EXPIRED")


def _mark_skip_unresolved(
    work: dict[str, Any],
    batch: dict[str, Any],
    skip_submission: dict[str, Any],
    *,
    revision: int,
) -> list[dict[str, Any]]:
    """Append human-readable unresolved records for every skipped card field."""

    existing = copy.deepcopy(work.get("unresolved")) if isinstance(work.get("unresolved"), list) else []
    questions = batch.get("questions") if isinstance(batch.get("questions"), list) else []
    skipped_ids = {str(item) for item in skip_submission.get("skipped_question_ids", [])}
    batch_id = str(batch.get("batch_id") or "")
    evidence_turn_id = "skip-" + str(skip_submission.get("skip_id") or batch_id)
    replacements: dict[str, dict[str, Any]] = {}
    for question in questions:
        if not isinstance(question, dict):
            continue
        question_id = _bounded_text(question.get("question_id"), max_chars=MAX_ID_CHARS)
        if not question_id or question_id not in skipped_ids:
            continue
        target_paths = [str(path) for path in (question.get("target_paths") or []) if _path_tokens(path)]
        reason_code = _bounded_text(question.get("reason_code"), max_chars=100) or "CLARIFICATION_SKIPPED"
        question_text = _bounded_text(question.get("text"), max_chars=4_000)
        summary = question_text or f"{reason_code} 확인"
        record_id = "unresolved-skip-" + hashlib.sha256(f"{batch_id}|{question_id}".encode("utf-8")).hexdigest()[:24]
        replacements[record_id] = {
            "id": record_id,
            "value": f"추가 입력 건너뜀: {summary}",
            "kind": "clarification_skipped",
            "skip_action": SKIP_ACTION,
            "batch_id": batch_id,
            "question_id": question_id,
            "reason_code": reason_code,
            "target_paths": target_paths,
            "provenance": {
                "status": "unknown",
                "evidence_turn_ids": [evidence_turn_id],
                "confidence": 0.0,
                "last_updated_revision": revision,
            },
        }
    retained = [item for item in existing if not (isinstance(item, dict) and item.get("id") in replacements)]
    unresolved = (retained + list(replacements.values()))[-1_000:]
    work["unresolved"] = unresolved
    return list(replacements.values())


def _canonical_native_submission(
    batch: dict[str, Any],
    native: dict[str, Any],
    *,
    actor_id: str,
    round_number: int,
    now: datetime,
) -> tuple[dict[str, Any], str]:
    """Validate a direct Playground answer and shape it like the old form record."""

    if str(native.get("action_id") or "") != "submit_answers":
        raise ValueError("NATIVE_ANSWER_ACTION_INVALID")
    for name in (
        "batch_id",
        "work_definition_id",
        "tenant_id",
        "owner_id",
        "session_id",
        "channel_mode",
        "revision",
        "round_number",
    ):
        if name not in native or str(native.get(name)) != str(batch.get(name)):
            raise ValueError("NATIVE_ANSWER_CONTEXT_MISMATCH")
    if int(native.get("round_number", -1)) != int(round_number):
        raise ValueError("CLARIFICATION_ROUND_MISMATCH")
    if str(native.get("owner_id") or "") != actor_id:
        raise ValueError("ACTION_ACTOR_MISMATCH")
    request_id = _bounded_text(native.get("request_id"), max_chars=MAX_ID_CHARS)
    raw_answers = native.get("answers")
    if not request_id or not isinstance(raw_answers, list) or not raw_answers:
        raise ValueError("NATIVE_ANSWER_SUBMISSION_INVALID")
    answers: list[dict[str, Any]] = []
    for item in raw_answers[:MAX_QUESTIONS]:
        if not isinstance(item, dict):
            raise ValueError("NATIVE_ANSWER_SUBMISSION_INVALID")
        question_id = _bounded_text(item.get("question_id"), max_chars=MAX_ID_CHARS)
        if not question_id:
            raise ValueError("NATIVE_ANSWER_SUBMISSION_INVALID")
        answers.append(
            {
                "question_id": question_id,
                "value": copy.deepcopy(item.get("value")),
                "resolve_conflict": bool(item.get("resolve_conflict", False)),
                "evidence_turn_id": _bounded_text(item.get("evidence_turn_id") or request_id, max_chars=MAX_ID_CHARS),
            }
        )
    if len(raw_answers) > MAX_QUESTIONS:
        raise ValueError("NATIVE_ANSWER_SUBMISSION_INVALID")
    material = _canonical(
        {
            "batch_id": batch.get("batch_id"),
            "request_id": request_id,
            "answers": answers,
        }
    )
    request_hash = hashlib.sha256(material.encode("utf-8")).hexdigest()
    idempotency_key = "native-hitl-" + request_hash
    submission_id = "answer-" + hashlib.sha256(f"{batch.get('batch_id')}|{idempotency_key}|{request_hash}".encode("utf-8")).hexdigest()[:24]
    submission = {
        "schema_version": "work-answer-submission/v1",
        "submission_id": submission_id,
        "idempotency_key": idempotency_key,
        "channel_mode": batch.get("channel_mode"),
        "work_definition_id": batch.get("work_definition_id"),
        "tenant_id": batch.get("tenant_id"),
        "session_id": batch.get("session_id"),
        "batch_id": batch.get("batch_id"),
        "expected_revision": int(batch.get("revision")),
        "answers": answers,
        "submitted_at": now,
        "actor_id": actor_id,
        "request_id": request_id,
    }
    return submission, request_hash


def _native_pending_batch(
    batch: dict[str, Any],
    native: dict[str, Any],
    *,
    actor_id: str,
    round_number: int,
    now: datetime,
) -> tuple[dict[str, Any], dict[str, Any], str]:
    """Create, but do not persist, the canonical pending native submission."""

    submission, request_hash = _canonical_native_submission(
        batch,
        native,
        actor_id=actor_id,
        round_number=round_number,
        now=now,
    )
    candidate = copy.deepcopy(batch)
    candidate["status"] = "ANSWERED_PENDING_RESUME"
    candidate["answer_submission"] = copy.deepcopy(submission)
    candidate["submission_idempotency_key"] = str(submission["idempotency_key"])
    candidate["submission_request_hash"] = request_hash
    return candidate, submission, request_hash


def _persist_native_submission(
    batches: Any,
    batch: dict[str, Any],
    native: dict[str, Any],
    *,
    actor_id: str,
    round_number: int,
    now: datetime,
) -> tuple[dict[str, Any], str]:
    """Atomically attach the direct-card answer to the immutable question batch.

    ``replace_one`` with the pending status is a small compare-and-set: a
    second click/retry can only reuse the exact same idempotency key and never
    overwrite a different answer submitted for the same question batch.
    """

    candidate, submission, request_hash = _native_pending_batch(
        batch,
        native,
        actor_id=actor_id,
        round_number=round_number,
        now=now,
    )
    idempotency_key = str(submission["idempotency_key"])
    identity = {
        "tenant_id": batch.get("tenant_id"),
        "work_definition_id": batch.get("work_definition_id"),
        "batch_id": batch.get("batch_id"),
        "status": "WAITING_ANSWER",
    }
    write = batches.replace_one(identity, candidate)
    if int(getattr(write, "matched_count", 0)) == 1:
        return candidate, str(submission["submission_id"])
    current = batches.find_one(
        {
            "tenant_id": batch.get("tenant_id"),
            "work_definition_id": batch.get("work_definition_id"),
            "batch_id": batch.get("batch_id"),
        }
    )
    if not isinstance(current, dict):
        raise ValueError("ANSWER_BATCH_NOT_FOUND")
    current_submission = current.get("answer_submission") if isinstance(current.get("answer_submission"), dict) else {}
    if (
        str(current.get("status") or "") in {"ANSWERED_PENDING_RESUME", "RESUMED"}
        and str(current_submission.get("idempotency_key") or "") == idempotency_key
        and str(current.get("submission_request_hash") or "") == request_hash
    ):
        return current, str(current_submission.get("submission_id") or submission["submission_id"])
    raise ValueError("NATIVE_ANSWER_ALREADY_SUBMITTED")


def _mark_native_submission_resumed(
    batches: Any,
    batch: dict[str, Any],
    submission_id: str,
    result: dict[str, Any],
    *,
    now: datetime,
) -> None:
    """Best-effort terminal audit stamp after the WorkDefinition CAS succeeds."""

    try:
        current = batches.find_one(
            {
                "tenant_id": batch.get("tenant_id"),
                "work_definition_id": batch.get("work_definition_id"),
                "batch_id": batch.get("batch_id"),
            }
        )
        if not isinstance(current, dict) or str(current.get("status") or "") == "RESUMED":
            return
        submission = current.get("answer_submission") if isinstance(current.get("answer_submission"), dict) else {}
        if str(submission.get("submission_id") or "") != submission_id:
            return
        current["status"] = "RESUMED"
        current["resumed_at"] = now
        current["resume_result"] = {
            "ok": bool(result.get("ok")),
            "status": str(result.get("status") or ""),
            "route": result.get("route"),
            "revision": ((result.get("work_definition") or {}).get("revision") if isinstance(result.get("work_definition"), dict) else None),
        }
        batches.replace_one(
            {
                "tenant_id": batch.get("tenant_id"),
                "work_definition_id": batch.get("work_definition_id"),
                "batch_id": batch.get("batch_id"),
                "status": "ANSWERED_PENDING_RESUME",
            },
            current,
        )
    except PyMongoError:
        # The canonical WorkDefinition has already been safely written.  A
        # later retry with the same idempotency key can complete this audit mark.
        return


def _mark_native_skip_resumed(
    batches: Any,
