        submission = current.get("skip_submission") if isinstance(current.get("skip_submission"), dict) else {}
        if str(submission.get("skip_id") or "") != skip_id:
            return
        current["status"] = "RESUMED"
        current["resumed_at"] = now
        current["resume_result"] = {
