}


def _payload(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        payload = copy.deepcopy(value)
    else:
        data = getattr(value, "data", None)
        if isinstance(data, dict):
            payload = copy.deepcopy(data)
        else:
            text = getattr(value, "text", value if isinstance(value, str) else "")
            payload = json.loads(re.sub(r"^```(?:json)?\s*|\s*```$", "", text.strip(), flags=re.IGNORECASE)) if isinstance(text, str) and text.strip() else {}
    return payload


def _canonicalize(value: Any, parent_key: str = "") -> Any:
    if isinstance(value, dict):
        result: dict[str, Any] = {}
        for key in sorted(value):
            if key in NON_SEMANTIC_KEYS or key.startswith("ui_") or key.startswith("render_"):
                continue
            result[key] = _canonicalize(value[key], key)
        return result
    if isinstance(value, list):
        items = [_canonicalize(item, parent_key) for item in value]
        if parent_key in UNORDERED_LIST_KEYS:
            items.sort(key=lambda item: json.dumps(item, ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=str))
        return items
    if isinstance(value, float):
        return float(format(value, ".15g"))
    return value


def build_work_preview_hash(value: Any) -> dict[str, Any]:
    trace_id = f"trace-{uuid.uuid4()}"
    try:
        envelope = _payload(value)
    except (TypeError, ValueError, json.JSONDecodeError):
        envelope = {}
    if envelope.get("ok") is not True:
        upstream_error = envelope.get("error") if isinstance(envelope.get("error"), dict) else {}
        return {
            "ok": False,
            "status": "BLOCKED",
            "artifact_refs": [],
            "error": {
                "code": "WORK_PREVIEW_UPSTREAM_REJECTED",
                "message": "성공한 업무 graph 검증 결과만 승인 Preview로 만들 수 있습니다.",
                "retryable": False,
                "details": {"upstream_error_code": upstream_error.get("code")},
            },
            "resume": None,
            "trace_id": trace_id,
        }
    graph_validation = envelope.get("graph_validation")
    work = envelope.get("work_definition")
    if not isinstance(work, dict) or not isinstance(graph_validation, dict) or graph_validation.get("valid") is not True:
        return {
            "ok": False,
            "status": "BLOCKED",
            "artifact_refs": [],
            "error": {
                "code": "WORK_PREVIEW_GRAPH_ATTESTATION_REQUIRED",
                "message": "유효한 WorkGraphNormalizer 검증 증거가 필요합니다.",
                "retryable": False,
                "details": {},
            },
            "resume": None,
            "trace_id": trace_id,
        }
    missing = [key for key in ("work_definition_id", "tenant_id", "revision", "as_is_graph") if work.get(key) in (None, "")]
    if missing:
        return {
            "ok": False,
            "status": "BLOCKED",
            "artifact_refs": [],
            "error": {"code": "WORK_PREVIEW_INPUT_INVALID", "message": "Preview hash를 만들 필수 WorkDefinition 필드가 없습니다.", "retryable": False, "details": {"fields": missing}},
            "resume": None,
            "trace_id": trace_id,
        }
    try:
        work_revision = int(work["revision"])
    except (TypeError, ValueError):
        return {
            "ok": False,
            "status": "BLOCKED",
            "artifact_refs": [],
            "error": {"code": "WORK_PREVIEW_REVISION_INVALID", "message": "Preview 대상 revision은 정수여야 합니다.", "retryable": False, "details": {}},
            "resume": None,
            "trace_id": trace_id,
        }
    graph = work.get("as_is_graph")
    if not isinstance(graph, dict) or not isinstance(graph.get("nodes"), list) or not isinstance(graph.get("edges"), list):
        return {
            "ok": False,
            "status": "BLOCKED",
            "artifact_refs": [],
            "error": {"code": "WORK_PREVIEW_GRAPH_INVALID", "message": "검증 가능한 AS-IS graph가 없습니다.", "retryable": False, "details": {}},
            "resume": None,
            "trace_id": trace_id,
        }

    semantic = {field: copy.deepcopy(work.get(field)) for field in SEMANTIC_FIELDS}
    # New F10 records preserve a sealed intake fragment so an ordinary
    # Playground chat reply can safely resume after Component 10 is excluded.
    # Keep its presence conditional: older approved records do not have this
    # field and must retain their already-published approval hash.
    if "f10_design_context" in work:
        semantic["f10_design_context"] = copy.deepcopy(work.get("f10_design_context"))
    canonical_preview = _canonicalize(semantic)
    try:
        canonical_text = json.dumps(canonical_preview, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)
    except (TypeError, ValueError):
        return {
            "ok": False,
            "status": "BLOCKED",
            "artifact_refs": [],
            "error": {"code": "WORK_PREVIEW_NON_CANONICAL_VALUE", "message": "업무 의미 필드에 canonical JSON으로 표현할 수 없는 값이 있습니다.", "retryable": False, "details": {}},
            "resume": None,
            "trace_id": trace_id,
        }
    preview_hash = "sha256:" + hashlib.sha256(canonical_text.encode("utf-8")).hexdigest()
    previous_preview = work.get("preview_hash")
    previous_approved = work.get("approved_hash")
    changed = bool(previous_preview and previous_preview != preview_hash)
    updated = copy.deepcopy(work)
    updated["preview_hash"] = preview_hash
    approval_invalidated = bool(previous_approved and previous_approved != preview_hash)
    if approval_invalidated:
        updated["approved_hash"] = None
        updated["status"] = "READY_FOR_REVIEW"
    elif previous_approved == preview_hash:
        updated["status"] = "APPROVED"
    else:
        updated["status"] = "READY_FOR_REVIEW"
    return {
        "ok": True,
        "status": updated["status"],
        "artifact_refs": [{"kind": "work_definition_preview", "id": work["work_definition_id"], "revision": work_revision, "sha256": preview_hash}],
        "work_definition": updated,
        "preview": {
            "schema_version": "work-definition-preview/v1",
            "work_definition_id": work["work_definition_id"],
            "revision": work_revision,
            "preview_hash": preview_hash,
            "canonical_json": canonical_text,
            "changed": changed,
            "approval_invalidated": approval_invalidated,
        },
        "trace_id": trace_id,
    }


class WorkPreviewHasherComponent(Component):
    display_name = "17 업무 Preview Hash"
    description = "유효한 WorkGraphNormalizer 증거를 확인한 뒤 UI 좌표와 시각·시간·trace 필드를 제외한 업무 의미 JSON을 canonicalize하고 승인 SHA-256을 계산합니다."
    icon = "Fingerprint"
    name = "WorkPreviewHasher"

    inputs = [
        DataInput(name="work_definition", display_name="WorkGraphNormalizer 검증 결과", input_types=["Data", "JSON"], required=True),
        DataInput(
            name="route_trigger",
            display_name="READY_FOR_REVIEW Route Trigger",
            input_types=["Data", "JSON", "Message"],
            required=False,
            advanced=True,
            info="Optional control dependency from a conditional router; excluded from the canonical hash.",
        ),
    ]
    outputs = [
        Output(name="preview", display_name="Canonical Preview", method="build_preview", types=["Data"]),
        Output(name="success_path", display_name="Preview 생성 성공", method="route_preview", types=["Data"], group_outputs=True),
        Output(name="blocked_path", display_name="Preview 생성 차단", method="route_preview", types=["Data"], group_outputs=True),
    ]

    def _result(self) -> dict[str, Any]:
        result = getattr(self, "_preview_result", None)
        if isinstance(result, dict):
            return result
        result = build_work_preview_hash(getattr(self, "work_definition", None))
        self._preview_result = result
        self.status = {
            "ok": result["ok"],
            "status": result["status"],
            "preview_hash": (result.get("preview") or {}).get("preview_hash"),
        }
        return result

    def build_preview(self) -> Data:
        return Data(data=self._result())

    def _component_id(self) -> str:
        return str(getattr(self, "_id", "") or self.name)[:200]

    def _select_output_route(self, selected: str) -> None:
        output_names = ("success_path", "blocked_path")
        non_selected = [output_name for output_name in output_names if output_name != selected]
        for output_name in non_selected:
            self.stop(output_name)
        graph = getattr(self, "graph", None)
        exclude = getattr(graph, "exclude_branches_conditionally", None) if graph is not None else None
        if callable(exclude):
            exclude(self._component_id(), non_selected)

    def _is_nonselected_group_output(self, selected: str) -> bool:
        current_output = str(getattr(self, "_current_output", "") or "")
        return bool(current_output and current_output in {"success_path", "blocked_path"} and current_output != selected)

    def route_preview(self) -> Data:
        result = self._result()
        selected = "success_path" if result.get("ok") is True else "blocked_path"
        self._select_output_route(selected)
        if self._is_nonselected_group_output(selected):
            return Data(data={})
        return Data(data=result)

"""Human Input node: pause a flow for a human decision, then route on the pick (LE-1449).

The User Choices picker chooses which actions the human can take (presets like
Approve/Reject/Escalate, or custom); each becomes a branch output. On first execution
the node requests a pause carrying a ``node_input`` request; on resume the injected
decision selects exactly one branch (the others are stopped). With Enable Fallback on,
a ``fallback`` branch is added for when no user action is answered (e.g. after timeout).
"""

from __future__ import annotations

from datetime import datetime, timezone
from typing import Any

from lfx.custom import Component
from lfx.inputs.inputs import ActionPickerInput, BoolInput, DurationInput
from lfx.io import MultilineInput, Output
from lfx.schema.message import Message

HUMAN_INPUT_REQUIRED = "human_input_required"
_KIND_NODE_INPUT = "node_input"
_FALLBACK_ACTION = "fallback"
_UNIT_SECONDS = {"Minutes": 60, "Hours": 3600, "Days": 86400}


def _action_id(label: str) -> str:
    """Stable branch id for a human-facing action label (e.g. 'Request Changes' -> 'request_changes')."""
    return str(label).strip().lower().replace(" ", "_")


class HumanInput(Component):
    display_name = "Human Input"
    description = "Pause the flow for a human-in-the-loop (HITL) decision and route on the chosen action."
    icon = "HumanInput"
    name = "HumanInput"
    metadata = {"keywords": ["hitl", "human-in-the-loop", "decision"]}

    inputs = [
        MultilineInput(
            name="prompt",
            display_name="Input",
            info="Content shown to the human for review.",
            value="",
        ),
        ActionPickerInput(
            name="decisions",
            display_name="User Choices",
            info="Choices the human can pick; each becomes a branch output. Pick from the list or type a custom one.",
            value=["Approve", "Reject"],
            real_time_refresh=True,
            required=True,
        ),
        DurationInput(
            name="timeout",
            display_name="Timeout",
            info="A response received after this window is rerouted to the fallback path (when enabled) "
            "instead of the chosen action. The run stays paused until a response arrives or the "
            "server's suspended-run deadline expires it. Set to 0 to wait indefinitely.",
            options=["Minutes", "Hours", "Days"],
            value={"value": 3, "unit": "Days"},
            advanced=True,
            show=False,
        ),
        BoolInput(
            name="enable_fallback",
            display_name="Enable Fallback",
            info="Add a 'fallback' output taken when the answer arrives after the timeout window.",
            value=False,
            advanced=True,
            real_time_refresh=True,
        ),
    ]

    # Default branch outputs mirror the default ``decisions`` so a freshly dragged
    # node shows handles immediately (update_outputs only fires on a field change).
    outputs: list[Output] = [
        Output(display_name="Approve", name="branch_approve", method="route_branch", group_outputs=True),
        Output(display_name="Reject", name="branch_reject", method="route_branch", group_outputs=True),
    ]

    async def update_frontend_node(self, new_frontend_node: dict, current_frontend_node: dict) -> dict:
        """Rebuild branch outputs from the saved User Choices so loaded/refreshed flows keep their handles."""
        new_frontend_node = await super().update_frontend_node(new_frontend_node, current_frontend_node)
        template = new_frontend_node.get("template", {})
        decisions = (template.get("decisions") or {}).get("value")
        self.update_outputs(new_frontend_node, "decisions", decisions if decisions is not None else [])
        self._sync_timeout_visibility(template)
        return new_frontend_node

    @staticmethod
    def _sync_timeout_visibility(template: dict) -> None:
        """Timeout only matters when the fallback branch exists to reroute to."""
        if "timeout" in template:
            template["timeout"]["show"] = bool((template.get("enable_fallback") or {}).get("value"))

    def update_build_config(self, build_config: dict, field_value: Any, field_name: str | None = None) -> dict:
        if field_name == "enable_fallback" and "timeout" in build_config:
            build_config["timeout"]["show"] = bool(field_value)
        return build_config

    def update_outputs(self, frontend_node: dict, field_name: str, field_value: Any) -> dict:
        """One branch output per selected action (+ optional fallback) + a stable action output."""
        if field_name not in ("decisions", "enable_fallback"):
            return frontend_node
        template = frontend_node.get("template", {})

        def _other(field: str, attr_default):
            if field in template:
                return (template.get(field) or {}).get("value")
            return getattr(self, attr_default[0], attr_default[1])

        actions = field_value if field_name == "decisions" else _other("decisions", ("decisions", []))
        fallback_on = (
            field_value if field_name == "enable_fallback" else _other("enable_fallback", ("enable_fallback", False))
        )
        outputs: list[Output] = []
        seen: set[str] = set()
        for label in actions or []:
            action_id = _action_id(label)
            if not action_id or action_id in seen:
                continue
            seen.add(action_id)
            outputs.append(
                Output(
                    display_name=str(label).strip(),
                    name=f"branch_{action_id}",
                    method="route_branch",
                    group_outputs=True,
                )
            )
        if fallback_on:
            outputs.append(
                Output(
                    display_name="Fallback",
                    name=f"branch_{_FALLBACK_ACTION}",
                    method="route_branch",
                    group_outputs=True,
                )
            )
        frontend_node["outputs"] = outputs
        return frontend_node

    def _actions(self) -> list[tuple[str, str]]:
        """Selected actions as (action_id, label) pairs, de-duplicated by id."""
        seen: set[str] = set()
        actions: list[tuple[str, str]] = []
        for label in getattr(self, "decisions", []) or []:
            action_id = _action_id(label)
            if not action_id or action_id in seen:
                continue
            seen.add(action_id)
            actions.append((action_id, str(label).strip()))
        return actions

    def _rendered_prompt(self) -> str:
        return str(getattr(self, "prompt", "") or "")

    def _timeout_seconds(self) -> int:
        timeout = getattr(self, "timeout", None) or {}
        if not isinstance(timeout, dict):
            return 0
        unit = timeout.get("unit", "Days") or "Days"
        return int(timeout.get("value", 0) or 0) * _UNIT_SECONDS.get(unit, _UNIT_SECONDS["Days"])

    def _request_id(self) -> str:
        run_id = str(getattr(self.graph, "run_id", "") or "")
        return f"{self._id}:{run_id}"

    def _injected_decision(self) -> dict | None:
        decisions = getattr(self.graph, "human_input_decisions", None) if self.graph is not None else None
        if not isinstance(decisions, dict):
            return None
        return decisions.get(self._request_id())

    def _allowed_decisions(self) -> list[str]:
        ids = [action_id for action_id, _ in self._actions()]
        if getattr(self, "enable_fallback", False):
            ids.append(_FALLBACK_ACTION)
        return ids

    def _pause_request(self) -> dict[str, Any]:
        return {
            "request_id": self._request_id(),
            "kind": _KIND_NODE_INPUT,
            "prompt": self._rendered_prompt(),
            "options": [{"action_id": action_id, "label": label} for action_id, label in self._actions()],
            "allowed_decisions": self._allowed_decisions(),
            "timeout_seconds": self._timeout_seconds(),
            "fallback_action": _FALLBACK_ACTION if getattr(self, "enable_fallback", False) else None,
            "paused_at": datetime.now(timezone.utc).isoformat(),
        }

    def _has_downstream_consumer(self) -> bool:
        """True if any branch output feeds a downstream node.

        A node with no outgoing edges runs as an isolated start vertex; pausing it would
        suspend the whole run for a decision that routes nowhere (and, alongside an Agent's
        own tool-approval pause, leave that pause unresolved on resume). The successor_map is
        absent only outside a prepared graph (standalone/tests), where the old behavior holds.
        """
        graph = getattr(self, "graph", None)
        successor_map = getattr(graph, "successor_map", None)
        if not isinstance(successor_map, dict):
            return True
        return bool(successor_map.get(self._id))

    def _suspend(self) -> None:
        self.graph.request_pause(reason=HUMAN_INPUT_REQUIRED, data=self._pause_request())
        self.status = "Awaiting human input"

    def route_branch(self) -> Message:
        decision = self._injected_decision()
        if decision is None:
            if not self._has_downstream_consumer():
                self.status = "Skipped: no connected outputs"
                return Message(text=self._rendered_prompt())
            self._suspend()
            return Message(text="")
        chosen = decision.get("action_id")
        non_chosen = [action_id for action_id in self._allowed_decisions() if action_id != chosen]
        for action_id in non_chosen:
            self.stop(f"branch_{action_id}")
        return Message(text=self._rendered_prompt())

from __future__ import annotations

"""Build one explicit authentication context for the F10 -> F20 boundary.

The work-request ``employee_id`` is an audit/owner hint, not an operating
authentication assertion.  This standalone component makes the distinction
visible on the F10 canvas:

* ``local_demo_fixture`` keeps the sample runnable, but marks the result as
  unverified and must never be described as production authentication.
* ``trusted_gateway`` accepts only the independently supplied gateway subject
  and groups.  It intentionally never falls back to the employee actor.

The downstream invocation loader consumes the sealed Data envelope rather
than a direct employee-id edge, so an imported production Flow has one
obvious identity boundary to replace with its gateway adapter.
"""

import copy
import json
import re
import uuid
from typing import Any

from lfx.custom import Component
from lfx.io import DataInput, DropdownInput, MessageTextInput, Output
from lfx.schema import Data


SCHEMA_VERSION = "f10-authentication-context/v1"
SOURCES = {"local_demo_fixture", "trusted_gateway"}
IDENTITY_PATTERN = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$")
MAX_GROUPS = 100
MAX_GROUP_INPUT_CHARS = 20_000
_OUTPUTS = ("success_path", "blocked_path")


def _payload(value: Any) -> Any:
    if isinstance(value, (dict, list, tuple, set)):
        return copy.deepcopy(value)
    data = getattr(value, "data", None)
    if isinstance(data, (dict, list, tuple, set)):
        return copy.deepcopy(data)
    text = getattr(value, "text", value if isinstance(value, str) else "")
    return text if isinstance(text, str) else ""


def _identity(value: Any) -> str:
    candidate = _payload(value)
    if isinstance(candidate, dict):
        for key in ("subject_id", "employee_id", "owner_id", "value", "text", "input_value"):
            if key in candidate:
                candidate = candidate[key]
                break
    if not isinstance(candidate, str):
        return ""
    text = candidate.strip()
    return text if IDENTITY_PATTERN.fullmatch(text) is not None else ""


def _groups(value: Any) -> list[str]:
    candidate = _payload(value)
    if isinstance(candidate, dict):
        if set(candidate) - {"groups"}:
            raise ValueError("AUTHENTICATION_GROUPS_INVALID")
        candidate = candidate.get("groups", [])
    if isinstance(candidate, str):
        if len(candidate) > MAX_GROUP_INPUT_CHARS:
            raise ValueError("AUTHENTICATION_GROUPS_LIMIT_EXCEEDED")
        text = candidate.strip()
        if not text:
            candidate = []
        elif text.startswith("[") or text.startswith("{"):
            try:
                candidate = json.loads(text)
            except json.JSONDecodeError as exc:
                raise ValueError("AUTHENTICATION_GROUPS_INVALID") from exc
            return _groups(candidate)
        else:
            candidate = re.split(r"[,;\n]", text)
    if not isinstance(candidate, (list, tuple, set)):
        raise ValueError("AUTHENTICATION_GROUPS_INVALID")
    if len(candidate) > MAX_GROUPS:
        raise ValueError("AUTHENTICATION_GROUPS_LIMIT_EXCEEDED")
    result: list[str] = []
    for item in candidate:
        identity = _identity(item)
        if not identity:
            raise ValueError("AUTHENTICATION_GROUPS_INVALID")
        normalized = identity.lower()
        if normalized not in result:
            result.append(normalized)
    return sorted(result)


def _failure(code: str, message: str, trace_id: str) -> dict[str, Any]:
    return {
        "ok": False,
        "status": "BLOCKED",
        "schema_version": SCHEMA_VERSION,
        "artifact_refs": [],
        "error": {"code": code, "message": message, "retryable": False, "details": {}},
        "resume": None,
        "trace_id": trace_id,
    }


def build_f10_authentication_context(
    *,
    authentication_source: Any,
    local_demo_employee_actor_id: Any = "",
    trusted_gateway_subject_id: Any = "",
    trusted_gateway_groups: Any = None,
    trace_id: Any = "",
) -> dict[str, Any]:
    """Create a bounded identity envelope without silently changing sources."""

    safe_trace = str(trace_id or f"trace-{uuid.uuid4()}")[:200]
    source = str(authentication_source or "").strip().lower()
    if source not in SOURCES:
        return _failure(
            "AUTHENTICATION_SOURCE_INVALID",
            "인증 source는 local_demo_fixture 또는 trusted_gateway여야 합니다.",
            safe_trace,
        )
    try:
        groups = _groups(trusted_gateway_groups)
    except ValueError as exc:
        return _failure(str(exc), "인증 group 형식이 유효하지 않습니다.", safe_trace)

    if source == "local_demo_fixture":
        subject_id = _identity(local_demo_employee_actor_id)
        if not subject_id:
            return _failure(
                "LOCAL_DEMO_SUBJECT_REQUIRED",
                "로컬 데모를 실행하려면 자동 연결된 사번 기반 실행자 ID가 필요합니다.",
                safe_trace,
            )
        if groups:
            return _failure(
                "LOCAL_DEMO_GROUPS_NOT_ALLOWED",
                "로컬 데모 인증에는 gateway group을 넣을 수 없습니다.",
                safe_trace,
            )
        verified = False
    else:
        subject_id = _identity(trusted_gateway_subject_id)
        if not subject_id:
            return _failure(
                "TRUSTED_GATEWAY_SUBJECT_REQUIRED",
                "운영 모드에서는 인증 gateway가 연결한 subject ID가 필요합니다.",
                safe_trace,
            )
        verified = True

    return {
        "ok": True,
        "status": "AUTHENTICATION_READY",
        "schema_version": SCHEMA_VERSION,
        "artifact_refs": [],
        "source": source,
        "subject_id": subject_id,
        "groups": groups,
        "authenticated_subject_verified": verified,
        "trace_id": safe_trace,
    }


class F10AuthenticationContextComponent(Component):
    display_name = "45 F10 인증 Context 경계"
    description = "로컬 데모 fixture와 운영 gateway 인증을 명시적으로 분리해 F10→F20 인증 context 하나를 만듭니다."
    icon = "ShieldUser"
    name = "F10AuthenticationContext"

    inputs = [
        DropdownInput(
            name="authentication_source",
            display_name="인증 Source",
            options=["local_demo_fixture", "trusted_gateway"],
            value="local_demo_fixture",
            info="local_demo_fixture는 예제 확인 전용이며 운영 인증으로 취급되지 않습니다. 운영에서는 trusted_gateway로 바꾸고 아래 gateway 포트를 연결합니다.",
        ),
        DataInput(
            name="local_demo_employee_actor_id",
            display_name="로컬 데모 사번 기반 실행자 (자동 연결)",
            input_types=["Data", "JSON", "Message"],
            required=False,
            info="Component 10의 사번 기반 실행자 ID가 자동 연결됩니다. local_demo_fixture에서만 사용하며 운영 gateway source에서는 무시됩니다.",
        ),
